'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["uk"]={"g-flurpruefung":["Що включає візуальний і функціональний огляд перед початком роботи?","Перед першою місією дня.","Перевіряйте лише рівень палива та колір автомобіля.","Перевірте гальма, рульове керування, вилки, шини та запобіжні пристрої відповідно до інструкції з експлуатації.","Проведіть пробну поїздку з піднятим вантажем.","Щоденна перевірка включає важливі для безпеки частини та функції відповідно до інструкції з експлуатації."],"g-rueckhalt":["Як ви ставитеся до існуючої системи безпеки водія?","Навантажувач має обов'язкову систему утримання.","Використовуйте його правильно під час водіння.","Використовуйте лише на нерівній підлозі.","Вимкніть його для коротких подорожей.","Передбачувані утримувальні системи повинні використовуватися відповідно до інструкцій виробника; вони забезпечують особливий захист у разі переломних подій."],"g-mangelmelden":["Що стосується навантажувача з пошкодженою вилкою?","Під час перевірки ви помітили явно погнутий зубець.","Якщо можливо, розподіліть навантаження на інший зуб.","Перевозіть лише легкі вантажі до наступного технічного обслуговування.","Не використовуйте навантажувач і повідомте про несправність відповідальній особі.","Пошкоджене вантажопідйомне обладнання може вийти з ладу; Дефекти, пов'язані з безпекою, вимагають відключення до з'ясування."],"g-einweisung":["Ви переходите на вилковий навантажувач з іншими елементами керування. Що потрібно перед використанням?","Операція відрізняється від вашого попереднього автомобіля.","Інструктаж щодо пристрою та дотримання інструкції з експлуатації.","Завжди достатньо короткого пояснення незаангажованого колеги.","Немає додаткової інформації, якщо у вас є ліцензія на навантажувач.","Загальна кваліфікація не замінює необхідної інструкції щодо фактично використовуваного пристрою."],"g-anbaugeraet":["Ви повинні використовувати вкладення. Що ви перевіряєте в першу чергу?","Нове обладнання змінює спосіб прийому вантажу.","Чи відповідає навісне обладнання сертифікації автомобіля та допустимому навантаженню.","Тільки чи можна прикріпити пристрій візуально.","Чи можна встановити навісне обладнання без документації.","Навісне обладнання може змінювати залишкову вантажопідйомність і центр навантаження; Дозволи та інформацію про вантажопідйомність необхідно перевірити."],"g-diagramm":["Навіщо потрібна схема вантажопідйомності?","Важкий вантаж присутній з центром ваги далеко назовні.","Щоб визначити найкоротший маршрут.","Для оцінки максимально допустимого навантаження в залежності від висоти підйому і центру навантаження.","Для визначення ємності бака.","Допустимі навантаження залежать, серед іншого, від відстані центру вантажу та висоти підйому."],"g-lastschwerpunkt":["Що зазвичай відбувається, коли центр ваги переміщується далі вперед?","Довгий вантаж виступає далеко перед вилами.","Допустима вантажопідйомність може зменшитися.","Вантажопідйомність постійно зростає.","Відстань не впливає на перекидний момент.","Більша відстань від центру навантаження збільшує перекидний момент і може зменшити допустиму вантажопідйомність."],"g-gabelabstand":["Як вила повинні підібрати відповідний піддон?","Ви хочете підібрати рівномірно завантажений піддон.","З зубцями якомога ближче і лише на одному куті.","З такою великою відстанню, що піддон перекидається набік.","З відповідною відстанню між зубцями та достатньою ходовою частиною та опорною площею.","Вантаж повинен підтримуватися надійно та якомога рівномірніше поперек вил."],"g-schieflast":["Вантаж покладено нестійко. Що правильно?","Картонні коробки можуть впасти при підйомі.","Почніть повільно; заряд стабілізується сам.","Перш ніж підняти вантаж, закріпіть його достатньою мірою або віддайте його знову зібрати.","Підніміть вантаж вище рівня голови, щоб він не заважав.","Розсипний або нестійкий вантаж може впасти та створити небезпеку для людей; в першу чергу дотримуйтеся заходів безпеки."],"g-personen":["Чи можна підняти людину на звичайних вилках?","Колега хоче дотягнутися до світла.","Так, якщо колега носить шолом.","Ні, лише призначені та дозволені об’єкти можуть використовуватися людьми відповідно до особливих вимог.","Так, якщо підійде лише невелика висота.","Звичайні вилки не є особистою робочою платформою; До транспортування та підйому людей пред'являються особливі вимоги."],"g-transporthoehe":["Як ви зазвичай транспортуєте піддон?","Дорога чиста і рівна.","З піднятим вантажем лише настільки, наскільки це необхідно та відповідно до інструкції з експлуатації.","З піднятим вантажем якомога вище, щоб було краще видно.","З підйомною щоглою, сильно нахиленою вперед, незалежно від навантаження.","Низьке транспортне положення знижує ризик перекидання та зіткнення; Вирішальне значення має інструкція до пристрою."],"g-kurvenfahrt":["Чому швидке проходження поворотів з навантажувачем небезпечне?","Ви хочете швидко зійти з вузької стежки.","Тому що він просто швидше розряджає акумулятор.","Тому що навантажувач автоматично керує краще.","Оскільки бічні сили впливають на стійкість і можуть призвести до перекидання.","При проходженні поворотів спрацьовують додаткові сили; швидкість повинна бути скоригована відповідно до навантаження та умов."],"g-ladebruecke":["Що ви перевіряєте перед тим, як заїхати на навантажувальний міст?","Ви повинні їхати у вантажівці.","Тільки чи дорога виглядає достатньо широкою.","Вантажопідйомність, надійна опора та захист від зсуву, а також надійна фіксація автомобіля.","Тільки чи вмикається освітлення.","Навантажувальні мости та транспортні засоби повинні бути захищені від руху та придатні для навантаження."],"g-fussgaenger":["Як поводитися на незрозумілому перехресті з пішоходами?","Візуальні з’єднання обмежені.","Рухайтесь із відповідною швидкістю, за необхідності зупиніться та забезпечте безпечну видимість.","Завжди вимагайте переваги під час перенесення вантажу.","Просто сигналіть і продовжуйте рух.","Пішоходи потребують особливого захисту; Швидкість, видимість і комунікація повинні бути адаптовані до маршруту руху."],"g-batterieladen":["На що слід звернути особливу увагу під час зарядки акумулятора накопичувача?","Використовується станція зарядки акумулятора.","Місце зарядки можна вибрати незалежно від інструкцій виробника.","Відкритий вогонь дозволяється, поки вантажівка стоїть на місці.","Відповідне місце для завантаження, достатня вентиляція та специфікації виробника, а також захист від пожежі та вибуху.","Під час заряджання небезпека може виникнути через електричну енергію, гази та хімічні речовини; необхідно дотримуватися передбачених захисних заходів."],"h-beauftragt":["За яких умов дозволяється самостійно керувати автовишкою?","Ви повинні використовувати робочу платформу в компанії.","Якщо у вас є водійські права.","Якщо ви підходите, проінструктовані або кваліфіковані та доручені роботодавцем.","Якщо ви коли-небудь бачили робочу платформу.","Роботодавець повинен забезпечити придатність, кваліфікацію та призначення відповідно до операційних вимог."],"h-vorpruefung":["Що необхідно перевірити перед початком роботи з підйомною платформою?","Вночі сцена стояла надворі.","Візуальна та функціональна перевірка відповідно до інструкцій виробника, включаючи пристрої безпеки.","Просто колір і вік сцени.","Чи є робочий матеріал уже на платформі.","Перед використанням машину, елементи керування, аварійні функції та видимі пошкодження необхідно перевірити відповідно до інструкції з експлуатації."],"h-tragfaehigkeit":["Яка інформація визначає допустиме навантаження на робочий кошик?","Двоє людей хотіли б взяти з собою додаткові інструменти.","Люди самі можуть оцінити допустиму загальну вагу.","Враховується лише вага найважчої людини.","Специфікація вантажопідйомності для людей, інструментів і матеріалів не повинна бути перевищена.","Номінальне навантаження відноситься до загального допустимого навантаження, включаючи будь-який матеріал, що перевозиться."],"h-untergrund":["Що ви враховуєте перед встановленням сцени з опорами?","Ви працюєте поблизу заповненої території.","Тільки в межах досяжності стріли.","Перевірте несучу здатність і рівність основи, а також відповідну опору відповідно до інструкцій.","На мінімально можливій кількості висунутих опор.","Недостатній грунт або неправильна опора можуть призвести до втрати стійкості."],"h-wind":["Настає сильний вітер. Як ви до цього ставитесь?","Ви опиняєтеся перед відкритою сценою.","Дотримуйтесь обмежень виробника, і якщо вони перевищені, зупиніть роботу або безпечно опустіть кошик.","Витягніть платформу якомога далі, щоб вона була більш стійкою.","Реагуйте лише на падіння незакріплених предметів.","Вітрові умови, дозволені виробником, є експлуатаційними межами; Вітер може створювати небезпечні додаткові сили."],"h-strom":["Працювати доводиться біля повітряної лінії електропередач. Що має вирішальне значення?","Жива лінія в робочій зоні.","Шолом замінює дотримання безпечної дистанції.","Просто ізолюйте кошик і працюйте без координації.","Уточніть небезпечну зону та забезпечте необхідні захисні відстані або інші відповідні заходи.","Електричний спалах також можливий без прямого контакту; Перед початком роботи необхідно визначити необхідні захисні заходи."],"h-notablass":["Навіщо потрібно знати порядок екстреного опускання?","Можливий збій нормального керування.","Щоб у разі несправності можливе безпечне порятунок відповідно до пристрою.","Щоб пристрій працював швидше в нормальному режимі роботи.","На заміну регулярним тестуванням.","Концепції аварійного керування, аварійного опускання та рятування повинні бути відомі та функціональні перед використанням."],"h-gelaender":["Як досягти додаткової висоти робочого кошика?","Точка монтажу просто недоступна.","Підніміться на огорожу кошика.","Помістіть дошку на перила.","Використовуйте відповідну платформу з достатньою робочою висотою; не залазити на перила.","Підйом на паркан або імпровізовані височини загрожує захисту від падіння."],"h-psaga":["Які вимоги ставляться до засобів індивідуального захисту від падіння?","Ви використовуєте робочу платформу, для якої передбачена система утримання.","Будь-яка опорна точка за межами кошика завжди достатня.","Дотримуйтеся оцінки ризику, інформації виробника та відповідних опорних точок.","Не використовуйте жодних засобів захисту, якщо кошик має поручні.","Те, чи потрібні ЗІЗ і які саме, визначається оцінкою ризику, конструкцією сцени та інструкціями з експлуатації."],"h-verfahren":["Чи можна пересувати сцену з піднятою платформою?","Робоче місце в декількох метрах.","Тільки якщо модель і умови експлуатації дозволяють це згідно з інструкцією виробника.","Завжди, поки всі тримаються.","Ні, ніколи, незалежно від конструкції та дозволу виробника.","Переміщення в піднятому положенні залежить від пристрою і дозволяється лише в дозволених умовах експлуатації."],"h-kollision":["Що потрібно організувати під час роботи біля кранів чи інших машин?","Рухомі частини можуть досягти робочого кошика.","Нічого; робочий кошик завжди видно.","Завжди ведіть робочий кошик над іншими машинами.","Координуйте робочі зони, щоб уникнути зіткнень або защемлень.","Одночасна робота машини вимагає скоординованих робочих процесів і захисту від зіткнень або заклинювання."],"h-einstieg":["Як зайти або вийти з робочого кошика?","Ви досягаєте кошика на рівні землі.","Перелізти через зовнішню огорожу.","Через передбачений доступ у безпечному місці відповідно до інструкції з експлуатації.","За допомогою драбини, розміщеної поруч із висунутою стрілою.","Необхідно дотримуватись інструкцій щодо передбачуваного доступу та інструкцій виробника; Неконтрольоване перелазіння створює ризик падіння."],"h-defekt":["Не працює система аварійної зупинки. що ти робиш","Дефект ви виявите під час огляду.","Не використовуйте платформу та повідомте про несправність.","Продовжуйте роботу, якщо нормальні елементи керування працюють.","Заклейте вимикач скотчем, щоб ніхто ним не керував.","Несправність запобіжного пристрою є дефектом, що має значення для безпеки та перешкоджає безпечній роботі."],"h-sicht":["Рух автомобіля не видно через перешкоду. Як ти до цього ставишся?","Слід пересунути мобільну сцену.","Їхати повільно без видимості.","Просто покладайтеся на індикатор відстані.","Припиніть рух і забезпечте видимість або безпечний інструктаж відповідно до інструкцій з експлуатації.","Перед процедурою необхідно безпечно оглянути людей, перешкоди та шляхи руху."],"h-rettung":["Що передбачає планування розгортання під час роботи на великих висотах?","Сцена використовується у віддаленій місцевості.","Тільки запланована тривалість роботи.","Відповідна концепція порятунку з доступними, навченими людьми та процедурами екстреного спуску.","Припущення, що пожежна служба негайно вирішить будь-яку проблему.","Ефективне порятунок має бути організовано заздалегідь, навіть якщо звичайний контроль не працює."],"k-befaehigung":["Що потрібно для самостійного керування краном?","Новий працівник повинен взяти на себе роботу крана.","Придатність та необхідна кваліфікація, інструктаж та відповідне завдання.","Достатньо посвідчення водія автомобіля.","Подивитись один раз достатньо.","Роботи крана можуть доручатися лише кваліфікованим та уповноваженим особам; Інструкція з обладнання є його частиною."],"k-funktionspruefung":["Що потрібно для перевірки крана перед початком зміни?","Ви приймаєте кімнатний кран.","Просто прочитайте час роботи на табличці.","Перевірте важливі для безпеки функції та видимі дефекти відповідно до інструкції з експлуатації.","Випробувати кран з максимальним навантаженням без перевірки.","Обов'язковий експлуатаційний контроль служить для виявлення небезпечних дефектів на ранній стадії."],"k-traglast":["Яке значення має допустиме навантаження?","Треба підняти вантаж.","Це необов'язкова рекомендація.","Він діє лише тоді, коли гак повністю втягнутий.","Не можна перевищувати допустиме навантаження для відповідних умов експлуатації.","Допустимі навантаження для окремих типів кранів можуть залежати від вильоту, положення стріли та озброєння."],"k-personen":["Що стосується людей під підвішеним вантажем?","Вантаж переміщується над робочою зоною.","Небезпечна зона повинна бути вільною; нікому не дозволяється наступати під підвішений вантаж.","Шолом дозволяє залишатися прямо під ним.","Короткі переходи допускаються, якщо кран рухається повільно.","Підвішені вантажі створюють ризик падіння та розчавлення; Люди повинні бути подалі від небезпечної зони."],"k-signale":["Ви не бачите зловмисника, і ви отримуєте суперечливі сигнали. що ти робиш","Комунікація незрозуміла.","Продовжити останню команду приводу.","Зупиніть рух і чітко уточніть спілкування.","Швидше скидайте навантаження, без консультації.","Для безпечного переміщення вантажу потрібні чіткі сигнали та чітка комунікація."],"k-sicht":["Хто буде підтримувати під час транспортування, якщо кранівник не може повністю бачити шлях вантажу?","Стовп залу закриває шлях.","Людина, яка проходить повз без попередньої домовленості.","ніхто; важливий тільки гачок.","Відповідна, проінструктована особа з чітко узгодженим розумінням.","Якщо шлях навантаження не видно, потрібна відповідна інструкція або інше безпечне рішення."],"k-ruck":["Чому слід уникати різких рухів крана?","Починає розгойдуватися важкий вантаж.","Вони створюють додаткові динамічні напруги і можуть дестабілізувати навантаження.","Вони в основному зменшують будь-який рух маятника.","Вони завжди збільшують номінальну вантажопідйомність.","Сили розгону і гальмування збільшують навантаження на кран і стропи."],"k-sperrbereich":["Що слід перевірити перед тим, як розгойдувати вантаж у спільній зоні?","Інші працівники працюють поруч.","Чи відповідає вантаж візуально крану.","Чи захищена небезпечна зона і чи немає людей під загрозою.","Чи можна нести вантаж якомога вище над усіма.","Поворотні та вантажні шляхи повинні бути вільними від незахищених людей."],"k-stuetzen":["Що важливо для автокрана з аутригерами?","Кран ставиться на частково засипаний ґрунт.","Просто ширина дороги.","Колір опорних плит.","Несуча основа, а також опора та розподіл навантаження відповідно до вказівок монтажу та виробника.","Установка має значний вплив на стійкість, особливо при зміні грунтових умов."],"k-wetter":["Порив вітру викликає значне розгойдування вантажу. Що правильно?","Ви працюєте на відкритому повітрі.","Безпечно зупиніть рух і дотримуйтеся допустимих умов експлуатації.","Швидко прискорити рух.","Продовжуйте піднімати вантаж, незважаючи на перевищення обмежень виробника.","Вітер і коливання можуть дестабілізувати вантаж і кран; Необхідно дотримуватися обмежень щодо застосування."],"k-freileitung":["Що стосується використання кранів поблизу повітряних ліній електропередач?","Стріла або вантаж можуть наблизитися до лінії.","При непровідному навантаженні зазори неважливі.","Уточніть небезпечну зону та необхідні захисні заходи з відповідальними особами перед початком роботи.","Покладайтеся лише на власну реакцію кранівника.","Існують небезпеки контакту та спалаху напруги; необхідні безпечні захисні відстані або інші заходи."],"k-sichern":["Що ви робите перед тим, як залишити кран?","Робота переривається.","Нехай вантаж висить.","Залишати кран без нагляду з працюючим приводом.","Безпечно опустіть вантаж і закріпіть кран відповідно до інструкції з експлуатації.","Підвішені вантажі не можна залишати без контролю; Кран і вантаж повинні бути безпечно припарковані."],"k-lastanschlag":["Як дізнатися, чи підходить використаний слінг?","Вантаж слід піднімати за допомогою підйомного ременя.","За маркуванням, вантажопідйомністю, станом і придатністю до типу кріплення.","Тільки за кольором підйомного ременя.","Тому що його вже використали вчора.","Вантажопідйомність і стан повинні бути достатніми з урахуванням умов кріплення."],"k-stopp":["Людина несподівано виходить на шлях вантажу. що ти робиш","Наразі кран переміщує вантаж.","Негайно безпечно зупиніть рух і звільніть небезпечну зону.","Просто дайте попереджувальний сигнал і продовжуйте рух.","Підніміть вантаж вище і проїдьте по ньому.","Люди повинні бути захищені від переміщення вантажу; Якщо є безпосередня небезпека, рух необхідно припинити."],"k-neuerkran":["Ви отримаєте кран з невідомим управлінням. Що правильно?","Елементи керування відрізняються від попередніх.","Спробуйте звичайні ключі, якщо підозрюєте.","Дозвольте комусь іншому без підготовки їхати попереду.","Перед самостійним використанням отримайте необхідну інструкцію щодо пристрою.","Навіть досвідченим кранівникам потрібні знання про конкретні засоби керування, що використовуються, захисні пристрої та обмеження."],"a-kennzeichnung":["Як дізнатися допустиму вантажопідйомність стропа?","Ви хочете вибрати слінг.","Запах матеріалу.","На відповідному, розбірливому маркуванні вантажопідйомності та інформації виробника.","За тривалістю зберігання.","Допустима вантажопідйомність визначається маркуванням і умовами експлуатації."],"a-sichtpruefung":["Ви помітили чіткий розріз підйомного ременя. Як ти до цього ставишся?","Гурт повинен нести навантаження.","Не використовуйте стрічку та надішліть її на тестування або бракування.","Заклейте зріз скотчем.","Використовуйте його лише для особливо невеликих навантажень.","Пошкоджені текстильні стропи можуть вийти з ладу, і їх необхідно оцінювати відповідно до критеріїв викиду."],"a-neigungswinkel":["Що станеться, якщо кут нахилу ниток стропа буде більшим за вертикальний?","Вішалка з двох ниток розкладається більше.","Зусилля нитки завжди зменшуються.","Зусилля нитки залишаються незмінними.","Збільшуються сили в пасмах; Необхідно дотримуватися допустимі кути нахилу та навантаження.","У міру збільшення розтягування збільшується сила розтягування на опорну нитку."],"a-schwerpunkt":["Навіщо потрібно знати центр ваги вантажу?","Навантаження формується нерівномірно.","Щоб вантаж залишався стабільним під час підйому та не перекидався неконтрольовано.","Для вибору кольору строп.","Щоб вантаж швидше обертався.","Несприятливі точки кріплення або положення центру ваги можуть призвести до перекидання, ковзання або похилих схилів."],"a-kantenschutz":["Підйомний ремінь прилягає до гострого краю компонента. Що треба зробити?","Компонент слід підняти.","Швидко піднімайте вантаж, поки ремінь не пошкодився.","Використовуйте відповідний захист для країв і перевірте тип кріплення.","Очищайте поверхню завантаження лише тканиною.","Гострі краї можуть пошкодити опорні волокна; обладнання для стропування повинно бути відповідним чином захищено."],"a-haken":["На що ви звертаєте увагу при кріпленні слінгу?","Ви використовуєте вантажний гак.","Помістіть строп збоку від кінчика гачка.","Тримайте захисну кришку постійно відкритою.","Завантажте гак за призначенням в основу гака та дотримуйтеся запобіжних пристроїв.","Недозволене навантаження на кінчик гачка та відсутність кріплення можуть призвести до його відчеплення."],"a-knoten":["Чи можна вкоротити надто довгий підйомний ремінь вузлом?","Довжина обмежувача не підходить.","ні; Використовуйте лише відповідний, схвалений тип стропи або відповідне обладнання для стропування.","Так, якщо вузол затягнутий дуже туго.","Так, поки вантаж нерухомий.","Вузли можуть значно послабити текстильні стропи, тому їх імпровізовані налаштування довжини не допускаються."],"a-probehub":["Чому вантаж спочатку піднімають обережно?","Ви хочете безпечно транспортувати.","Щоб вона могла якнайшвидше доїхати.","Перевірити положення строп, стійкість і центр ваги.","Оскільки вантажопідйомність збільшується автоматично.","Контрольований перший хід допомагає виявити неправильні зупинки та нестабільні положення вантажу."],"a-lastweg":["Де дозволяється перебувати людям під час транспортування вантажу?","Вантаж переміщується краном.","Безпосередньо під вантажем із захисним шоломом.","На ноші, якщо вони можуть витримати.","Поза небезпечною зоною і не під підвішеними вантажами.","Навіть при ретельному кріпленні все ще існує небезпека падіння або хитання вантажу."],"a-haende":["Як уникнути травм під час відлучення?","Вантаж наближається до опорної поверхні.","Тримайте руки та ноги подалі від зони розчавлення та використовуйте відповідні допоміжні засоби.","Тримайте вантаж голою рукою.","Встаньте між вантажем і стіною, щоб виправити положення.","Між вантажем і опорою виникають небезпечні точки защемлення."],"a-vierstraenge":["Що стосується розподілу навантаження на чотириногій підвісці без компенсації навантаження?","Прикріплений жорсткий вантаж.","Усі чотири нитки неминуче несуть однакову суму.","Без підтвердження рівномірного розподілу несучу здатність не можна використовувати як загальну оцінку для чотирьох однаково навантажених ниток.","Тоді кут нахилу не має значення.","При жорстких навантаженнях можливе неоднакове навантаження пасом; Конструкція та допустиме навантаження мають це враховувати."],"a-chemikalien":["Що стосується використання текстильних строп у контакті з хімікатами?","Ви працюєте з невідомою рідиною.","Колір стрічки достовірно свідчить про її довговічність.","Кожна текстильна стрічка стійка до всіх хімічних речовин.","Перевірте довговічність і інформацію про виробника; Не використовуйте невідповідні засоби.","Хімічні речовини можуть вразити стропи та непомітно зменшити їхню несучу здатність."],"a-aufbewahrung":["Як зберігаються стропи після використання?","Місія завершена.","Чисті, сухі та захищені від пошкоджень відповідно до специфікацій виробника.","Застряг на землі під незахищеним вантажем.","На будь-який гострий відкритий гачок.","Належне зберігання запобігає передчасному зносу та полегшує візуальний огляд."],"a-auswahl":["Що особливо слід враховувати для чутливих або гострих вантажів?","Пофарбований компонент машини потрібно перемістити.","Тільки транспортна швидкість.","Відповідні стропи та захисні засоби для вантажної поверхні та країв.","Незалежно від навантаження, завжди однаковий сталевий трос.","Тип кріплення та матеріал повинні відповідати геометрії, поверхні та небезпеці."],"a-abstimmung":["Кранівник вас не бачить. Як ви даєте вказівки?","Ви призначені в якості нападника.","Ви махаєте довільно, поки не почнеться рух.","Ти просто дзвониш і йдеш.","За допомогою чітко узгоджених знаків або іншого надійного зв’язку.","Зловмисники та кранівники повинні чітко спілкуватися; Якщо незрозуміло, рух потрібно припинити."],"b-qualifikation":["Що потрібно людині для безпечного керування гідравлічним екскаватором під час роботи?","Роботи на будівництві повинна взяти нова людина.","Відповідна кваліфікація, інструкції щодо пристрою та обов’язкове призначення.","Тільки посвідчення водія автомобіля.","Просто короткий огляд операції.","Роботодавець повинен забезпечити необхідну кваліфікацію та проінструктувати оператора відповідно до завдання."],"b-pruefung":["Що входить у щоденну перевірку машини?","Ви берете екскаватор.","Перевірте колір фарби та оббивку сидінь.","Візуальна перевірка та функціональні перевірки відповідно до інструкцій з експлуатації, наприклад, на наявність витоків і пошкоджень.","Рухайте стрілу на повній швидкості, доки вона не зупиниться.","Пошкодження гідравліки, шасі та пристроїв безпеки може призвести до серйозних нещасних випадків."],"b-leitungen":["Що потрібно знати про підземні труби перед розкопками?","Треба вирити котлован.","Тільки приблизна глибина запланованого котловану.","Кольору надземної розмітки достатньо.","Уточніть розташування можливих ліній і визначте відповідні заходи безпеки та розвідки.","Пошкодження електричних, газових або водопровідних труб може мати небезпечні для життя наслідки."],"b-schwenkbereich":["Як захистити людей в зоні повороту екскаватора?","Ви забираєте матеріал за допомогою стріли.","Огородіть або огородіть небезпечну зону та не допускайте людей.","Перед поворотом повільно рухайте лопату.","Проїжджайте по площі над головами.","Поворотна надбудова та знаряддя створюють небезпеку розчавлення та удару."],"b-boeschung":["Що важливо при роботі біля краю котловану?","Екскаватор стоїть на встановленому або насипаному ґрунті.","Тільки глибина копання визначає допустиме розміщення.","Зверніть увагу на несучу здатність і кріплення краю, а також на необхідні відстані відповідно до оцінки ризику.","Проїжджайте якомога ближче до краю, щоб зберегти дальність.","За недостатнього просвіту або стійкого ґрунту насип може зруйнуватися, і машина може впасти."],"b-standsicherheit":["Чому нахил і ґрунт мають вирішальне значення для використання?","Будмайданчик знаходиться на схилі.","Машина однаково стійка на будь-якій поверхні.","Гусеничні ходові частини виключають ризик перекидання.","Нерівності та схили можуть вплинути на стійкість; Дотримуватися обмежень застосування.","Стійкість і безпека перекидання залежить від підлоги, обладнання, навантаження та положення машини."],"b-wechselgeraet":["Що ви перевіряєте після заміни ковша екскаватора за допомогою швидкозчіпного пристрою?","Встановлено нове кріплення.","Чи правильно він заблокований і закріплений відповідно до інструкцій з експлуатації.","Тільки чи збігається колір лопати.","Чи працює гідравліка максимально тихо.","Несправні замки можуть спричинити падіння навісного обладнання."],"b-heben":["На що слід звернути увагу під час підіймання екскаватором вантажу, що вільно висить?","Екскаватор використовується для підйомних робіт.","Вирішальним є лише звичайне зусилля копання.","Дотримуйтеся допустимого підйомного навантаження, відповідних точок кріплення та встановлених захисних пристроїв.","Вантаж можна зачепити за зуби ковша.","Підйом дозволяється лише в межах передбачених умов експлуатації за допомогою відповідного обладнання."],"b-rueckwaerts":["Треба заднім ходом, але дороги не видно. Що правильно?","Інші працівники поруч.","Їдьте обережно без видимості.","Просто сигналіть і продовжуйте рух.","Зупиніться, забезпечте видимість і небезпечну зону або організуйте відповідні інструкції.","Рух заднім ходом не повинен загрожувати людям; обмежена видимість вимагає додаткових заходів."],"b-kabel":["Стріла могла наблизитися до повітряної лінії електропередач. що ти робиш","Ви працюєте на тісному будівельному майданчику.","Заздалегідь уточніть з відповідальними особами небезпечну зону та відповідні захисні заходи.","Ігноруйте лінію, якщо стріла пофарбована.","Пересувайте стрілу тільки особливо швидко.","Небезпека ураження електричним струмом виникає через контакт і спалах; необхідні безпечні відстані та заходи захисту."],"b-verlassen":["Як припаркувати екскаватор перед виїздом?","Ви робите перерву.","Залиште стрілу вільно плавати.","Безпечно встановіть робоче обладнання та захистіть машину від переміщення та несанкціонованого використання.","Залиште двигун працюючим, а кабіну відкритою.","Опущене робоче обладнання та захист від ненавмисного переміщення зменшують ризик нещасних випадків."],"b-hydraulik":["Ви помітили гідравлічне масло під високим тиском на пошкодженій лінії. Що правильно?","Протікає лінія.","Відчуйте витік рукою.","Прикріпіть новий хомут під тиском.","Безпечно вимкніть машину, дайте знизити тиск і доручіть проведення ремонту уповноваженим спеціалістам.","Гідравлічна рідина під високим тиском може спричинити серйозні травми; ніколи не перевіряйте витоки вручну."],"b-unterbau":["Чим небезпечна їзда по нестійкій поверхні?","Земля м'яка після дощу.","Машина може потонути, зісковзнути або перекинутися.","Привід автоматично стає ширшим.","Це робить діапазон повороту безпечнішим.","Недостатня вантажопідйомність може значно погіршити стабільність і безпеку водіння."],"b-arbeitsgeraet":["Чи може хтось працювати під піднятим знаряддям?","Людина хоче щось під лопатою контролювати.","Так, коли двигун працює на холостому ходу.","Ні, не без необхідної безпечної підтримки та кріплення робочого обладнання.","Так, якщо людина носить захисний шолом.","Гідравлічне обладнання може тонути; Роботи з технічного обслуговування вимагають безпечного робочого обладнання."],"b-geraeteart":["Ви переходите з гідравлічного екскаватора на фронтальний навантажувач. Що потрібно?","Поведінка при роботі та русі відрізняється.","Таке ж взуття.","Тест драйв без інструкції.","Кваліфікація або інструкція, необхідна для нового типу машини.","Кваліфікація повинна відповідати типу машини, що використовується, і конкретним експлуатаційним вимогам."],"g-neigung":["Ви керуєте завантаженим навантажувачем на схилі. Що важливо?","Траса має чіткий ухил.","Завжди направляйте вантаж вниз, навіть якщо він важкий.","Направляйте вантаж угору та дотримуйтеся вказівок щодо експлуатації на схилах.","Незалежно від напрямку руху, піднімайте вилку на максимум.","На підйомах і спусках вантаж завжди потрібно нести в гору; Слід дотримуватися інструкції з експлуатації транспортного засобу."],"g-gabelabsenken":["Чому при паркуванні вилка повинна бути опущена?","Навантажувач припаркований для перерви.","Щоб інші могли використовувати вилку, щоб піднятися вгору.","Щоб вилка залишалася більш помітною здалеку.","Щоб підняття вантажу не створювало непотрібного ризику спіткнутися або отримати травму.","Опущені пристрої для завантаження вантажу зменшують ризик нещасних випадків через виступаючі або незакріплені вила."],"g-fahrerwechsel":["Колега хотів би позичити навантажувач. Що має бути присутнім?","Колега має лише усний дозвіл від вас.","Він повинен мати необхідну кваліфікацію та повноваження компанії.","Ваше власне призначення також автоматично поширюється на нього.","Для будь-якого бізнесу достатньо посвідчення водія приватного автомобіля.","Незалежне керівництво пов'язане з особистою придатністю, навчанням, кваліфікацією та оперативним призначенням."],"g-ladungssicherung":["Піддон містить коробки, складені один на один. Що правильно?","Під час руху картонна коробка може впасти.","Перед транспортуванням зафіксуйте вантаж від ковзання та падіння.","Їдьте повільно лише на особливо нерівній поверхні.","Компенсуйте вільні ящики вищим положенням вилки.","Вантаж повинен бути стійким і захищеним від падіння перед транспортуванням за допомогою вантажівки."],"g-bodenbelastung":["Перед вами ковдра з обмеженою несучою здатністю. Як ви вирішуєте?","Маршрут проходить через проміжний рівень.","Просто зверніть увагу на вагу вантажівки без вантажу.","Уточніть допустиме навантаження на підлогу для навантажувачів і вантажів.","Рухайтеся з інерцією, щоб стеля була під навантаженням протягом коротшого періоду часу.","Релевантним є загальне фактичне навантаження на територію, включаючи транспортний засіб, навантаження та динамічні впливи."],"g-verkehrswege":["Ваш шлях перетинає маркована стежка. Що правильно?","Пішоходи можуть вийти на перехід у будь-який час.","Ви завжди можете заявити про пріоритет за допомогою клаксона.","Дозволяється проїзд через розмітку без спостереження.","Змінюйте швидкість, звертайте увагу на пішоходів і продовжуйте рух лише тоді, коли дорога вільна.","Маршрути руху повинні проходити з урахуванням людей; Попереджувальні знаки не замінюють безпечної видимості та чіткого маршруту."],"g-parkbremse":["Ви паркуєте навантажувач на рівній землі. Що це включає?","Ви хочете покинути місце водія на кілька хвилин.","Припаркуйтеся, застосуйте стоянкове гальмо та захищайте від несанкціонованого використання.","Залишайте автомобіль лише в нейтральному положенні.","Залиште вилку на висоті голови, щоб її ніхто не торкався.","Перед виїздом вантажівку необхідно безпечно зупинити та зафіксувати від ненавмисного руху."],"g-typenschild":["Яка інформація є обов'язковою, коли мова йде про вантаж на навантажувачі?","Ви хочете взяти важку машину.","Розрахункова вантажопідйомність на основі розміру автомобіля.","Інформація виробника в діаграмі навантаження або вантажопідйомності.","Вага останнього транспортованого піддона.","Допустиме навантаження визначається інформацією виробника та залежить, серед іншого, від центру навантаження та висоти підйому."],"g-tore":["Ви під’їжджаєте до низького проходу з навантажувачем. Що ти перевіряєш?","На транспортному засобі лежить високий вантаж.","Чи можливий безпечний прохід, включаючи вантаж і кріплення.","Тільки висота вилкової каретки без вантажу.","Чи зможете ви проїхати швидше, перш ніж ворота закриються.","Перед проїздом слід враховувати висоту та ширину в чистому вигляді, а також розміри вантажу та транспортного засобу."],"g-reifen":["Під час щоденної перевірки ви виявили сильно пошкоджену шину. що ти робиш","На шині видно пошкодження, пов’язані з безпекою.","Ви їдете повільно до свого звичайного технічного обслуговування.","Ви збільшуєте тиск у шинах і продовжуєте їхати.","Ви не приймаєте транспортний засіб в експлуатацію і не повідомляєте про пошкодження.","Пошкоджені шини можуть погіршити стійкість і керованість; дефект необхідно з'ясувати перед використанням."],"h-absperren":["Під вашою робочою платформою проходять працівники. Що необхідно?","Існує небезпека падіння інструментів.","Відповідна захисна або закрита зона під робочим місцем.","Просто сповіщення, коли ви вперше проходите повз.","Зберігайте інструменти якомога далі від краю кошика.","Робоча зона під робочими місцями, що знаходяться на підвищенні, повинна бути захищена від небезпеки від падаючих частин."],"h-werkzeuge":["Як ви транспортуєте інструменти в робочому кошику?","На висоті знадобляться кілька дрібних інструментів.","Розмістіть їх вільно на поручні, щоб вони були в межах досяжності.","Зберігайте та закріплюйте таким чином, щоб вони не впали та не перешкоджали роботі.","Прикріпіть до зовнішньої сторони перил у кишені.","Незакріплені предмети можуть впасти та загрожувати людям; потрібне безпечне зберігання."],"h-abstuetzung":["Опора стоїть на кришці колодязя. Що потрібно перевірити?","Ви хочете підняти платформу.","Просто переконайтеся, що кришка суха.","Чи можна безпечно прийняти навантаження в цій точці.","Чи не потрібно використовувати інші опори.","Підґрунтя та контактні ділянки повинні бути здатні безпечно сприймати опорні сили; Обкладинки потрібно оцінювати окремо."],"h-notaus":["Коли слід використовувати пристрій аварійної зупинки?","Відразу виникає небезпечний рух.","Тільки в кінці чергової зміни.","Для зупинки в умовах гострої небезпеки відповідно до інструкції з експлуатації.","На заміну плановому опусканню.","Аварійна зупинка використовується для запобігання небезпеці, а не звичайний контроль або звичайне вимкнення."],"h-schraegstellung":["Спрацьовує попередження про нахил сцени. Як ви реагуєте?","Машина стоїть на похилій поверхні.","Ви ігноруєте попередження на низькій робочій висоті.","Незважаючи на попередження, ви їдете в найвище положення підйому.","Ви зупиняєтеся і приводить сцену в безпечний стан відповідно до інструкцій виробника.","Попередження про нахил можуть вказувати на недостатню стійкість; подальші рухи не повинні збільшувати небезпеку."],"h-umgebung":["Що потрібно організувати при облаштуванні біля зони руху?","Транспортні засоби можуть торкатися сцени.","Захист від зіткнень і відповідне керування дорожнім рухом.","Перекиньте робочий кошик якомога далі над дорогою.","Просто попереджувальний дзвінок перед завантаженням.","Підйомники повинні бути захищені від зіткнення з учасниками дорожнього руху; установку необхідно закріпити відповідним чином."],"h-ueberlast":["Спрацьовує попередження про перевантаження в кошику. що ти робиш","Були запрошені додаткові інструменти.","Закінчіть роботу на вищій швидкості.","Встановіть допустиме завантаження кошика та дотримуйтесь інструкцій виробника.","Вимкніть попереджувальний сигнал назавжди.","Не можна перевищувати максимально допустиме навантаження на кошик, включаючи людей і матеріали."],"h-quetschen":["Заганяєш кошик близько під дах. Яка небезпека є особливо важливою?","Над кошиком залишилося небагато місця.","Затискання або здавлювання між кошиком і конструкцією.","Щоб двигун споживав більше палива.","Щоб напрямок руху завжди змінювався автоматично.","Тісний простір над робочим кошиком або поруч із ним може спричинити серйозні травми."],"h-stromausfall":["Сцена залишається на великій висоті без основного приводу. Що правильно?","Звичайне керування кошиком більше не реагує.","Ви спускаєтеся зі стріли без безпеки.","Ви чекаєте до кінця вашої зміни без повідомлення.","Розпочніть підготовлене рятування за допомогою навчених людей і аварійного спуску.","Безпечне порятунок має бути сплановано на випадок збоїв; Навчені люди повинні знати аварійні функції."],"h-transportstellung":["Як створити основу для транспорту?","Підйомник завантажується на відповідний транспортний засіб.","Приведіть стрілу та платформу в транспортне положення відповідно до інструкції з експлуатації.","Прив’яжіть платформу якомога далі.","Залиште опори висунутими, щоб вони займали більше місця.","Зазначене транспортне положення та кріплення вантажу базуються на специфікаціях виробника та транспортуванні."],"k-bremsprobe":["Що показує перевірка роботи кранового гальма перед використанням?","Ви хочете надійно утримувати вантаж.","Чи зупиняється гальмо та утримує рух за призначенням.","Тільки чи працює освітлення салону.","Чи може гак автоматично утримувати вантаж.","Перед використанням необхідно перевірити важливі для безпеки функції відповідно до специфікацій."],"k-schraegzug":["Чи можете ви тягнути вантаж краном під кутом?","Гак не стоїть вертикально над вантажем.","Так, якщо кран ще має запас навантаження.","Ні, вантажі не можна тягнути за допомогою неприпустимих діагональних тяг.","Так, якщо слінги особливо короткі.","Діагональне перетягування може спричинити неконтрольовані рухи та додаткове навантаження на кран і стропи."],"k-verhakt":["На підконструкції висить вантаж. Що правильно?","При підйомі відчувається опір.","Ви продовжуєте піднімати, поки воно не відійде.","Ви ривками рухаєте вантаж убік.","Ви зупиняєтесь і безпечно видаляєте кріплення або блокування.","Застряглі вантажі не можна відривати силою, оскільки можуть виникнути неприйнятні зусилля."],"k-anzuheben":["Що ви перевіряєте, коли вперше коротко піднімаєте підвішений вантаж?","Вантаж піднімається на кілька сантиметрів від землі.","Незалежно від того, чи він висить у рівновазі, а зупинка надійна.","Чи може людина піддавати себе безпосередньо навантаженню.","Чи стає кран стабільнішим завдяки швидкому повороту.","Короткий контрольований підйом використовується для перевірки кріплення, рівноваги та безпечної поведінки вантажу."],"k-lastweg":["Де повинен пролягати шлях транспортування вантажу краном?","Кілька робочих місць знаходяться під можливим шляхом навантаження.","Якщо можливо, вище зайнятих робочих місць.","На спланованому, чіткому шляху без людей у ​​небезпеці.","Завжди по діагоналі через найбільш жваву зону.","Маршрути вантажу повинні бути організовані таким чином, щоб людям не загрожували підвішені вантажі."],"k-signalverlust":["Радіозв'язок з маршалом обривається. що ти робиш","Ви не бачите самого шляху навантаження.","Ви повільно продовжуєте рух.","Ви експериментально гойдаєтеся в попередньому напрямку.","Ви зупиняєте рух, поки не досягнете чіткого, безпечного розуміння.","У разі відсутності зв'язку переміщення заплутаного вантажу може не тривати."],"k-haken":["Запобіжний гачок не закривається надійно. Що правильно?","Під час огляду помічено несправне закриття.","Помилка повинна бути виправлена ​​професійно перед подальшим використанням.","Ви міцно зав’язуєте застібку кабельною стяжкою.","Ви використовуєте гак лише для легких вантажів.","Несправні кріпильні пристрої на вантажних гаках можуть призвести до того, що стропи від’єднаються, і їх необхідно усунути."],"k-zugrichtung":["Що важливо для вертикальної опори вантажу?","Вантаж необхідно підняти з машини.","Гак крана повинен бути вирівняний над центром ваги вантажу.","Гачок повинен бути розташований якомога збоку.","Перед підйомом вантаж необхідно штовхнути.","Силовий ефект, який є максимально вертикальним над центром навантаження, дозволяє уникнути неприпустимих бічних сил і неконтрольованого розгойдування."],"k-wartung":["На крані помічено незвичайний скрегіт. Як ти до цього ставишся?","Шум виникає при підйомі.","Прикрийте шум за допомогою високої швидкості.","Безпечно зупиняйте операції, повідомляйте про дефекти та вимагайте їх усунення.","Продовжити роботу без попередження до перерви.","Помітні зміни можуть свідчити про пошкодження, пов’язані з безпекою, і вимагати перевірки."],"k-absetzen":["Що необхідно гарантувати при опусканні вантажу крана?","На поверхні лежить важкий вантаж.","Вантаж може лежати незакріпленим на похилій поверхні.","Стропи знімають, поки він ще плаває.","Вантаж стійкий і захищений від перекидання або скочування.","Звільняти вантаж від стропування можна тільки після того, як він безпечно поставлений і встановлена ​​стійкість."],"l-schwerpunkt":["Чому перед ударом потрібно знати центр ваги?","Треба транспортувати машину асиметричної форми.","Щоб вантаж при підйомі залишався максимально збалансованим.","Щоб стропи можна було вибирати скільки завгодно довжини.","Так що допустима вантажопідйомність ролі не грає.","Положення центру ваги впливає на розподіл навантаження і безпечну рівновагу при підйомі."],"l-etikett":["Підйомний ремінь не має читабельної етикетки вантажопідйомності. Що правильно?","Маркування стало невпізнанним.","Оцініть вантажопідйомність за кольором.","Не використовуйте підйомний ремінь, доки його придатність не буде чітко продемонстрована.","Використовуйте ремінь лише один раз для невеликих навантажень.","Для стропів необхідне відповідне маркування; Незрозуміла вантажопідйомність перешкоджає безпечному вибору."],"l-kantenschutz":["Текстильна стрічка лежить на гострому сталевому краї. Що необхідно?","Вантаж має гострі краї.","Натягніть стрічку якомога щільніше без захисту.","Виконуйте гребок швидше.","Використовуйте відповідний захист країв або інше відповідне обладнання для стропування.","Гострі краї можуть пошкодити або порізати текстильні стропи; необхідний відповідний захист."],"l-spreizwinkel":["Як більший кут нахилу впливає на навантаження строп?","Вантаж піднімають за допомогою двох похилих мотузок.","При менш сприятливих кутах сили в нитках можуть збільшуватися.","Сили пасма зникають.","Кут не впливає на напругу.","При менш сприятливому куті зупинки сили на пасмо можуть збільшуватися; Необхідно дотримуватися таблиці вантажопідйомності."],"l-knoten":["Чи можна за бажанням вкоротити мотузку за допомогою вузла?","Мотузка занадто довга для запланованого навантаження.","Так, тугий вузол покращує вантажопідйомність.","Ні, використовуйте лише затверджені методи укорочення та кріплення.","Так, якщо вузол закріплений скотчем.","Недопустимі вузли послаблюють стропи і змінюють їх допустиму вантажопідйомність."],"l-zeichen":["Що стосується спілкування з особою, яка керує краном?","Шлях вантажу частково закритий.","Кілька людей подають різні сигнали одночасно.","Використовуються чіткі, попередньо узгоджені сигнали.","З радіокранами зв'язок ніколи не потрібен.","Чіткі знаки та чітка відповідальність запобігають небезпечним неправильним рухам."],"l-sichtpruefung":["Коли слід перевіряти стропи на наявність видимих ​​дефектів?","Ви хочете використовувати ланцюжок для стропи.","Перед використанням зверніть увагу на будь-які зовнішні пошкодження.","Тільки якщо аварія вже сталася.","Тільки один раз при першій покупці.","Перед кожним використанням необхідно оцінити безпечні умови роботи; Видимі пошкодження перешкоджають безпечному використанню."],"l-drehung":["Піднятий вантаж починає неконтрольовано обертатися. що ти робиш","Вантаж рухається по шляху навантаження.","Ви кладете руку між вантажем і стіною.","Ви кладете на себе тягар і тримаєтесь за нього.","Ви тримаєте дистанцію та дозволяєте рухові зупинитися контрольованим чином.","Неконтрольоване переміщення вантажу створює небезпеку розчавлення та удару; Люди повинні залишити небезпечну зону."],"l-ablegen":["Коли стропи можна знімати з вантажу?","Вантаж розміщується на естакадах.","Якщо вантаж стійкий і захищений від перекидання або скочування.","Як тільки він торкнеться землі вперше, незалежно від його положення.","Поки все ще зависає, щоб заощадити час.","Стропи можна знімати лише після того, як вони безпечно та стійко встановлені."],"l-ketten":["Ланцюговий строп має сильно зігнуту ланку. що ти робиш","Пошкодження видно ще до підняття.","Обмотайте пошкоджене місце дротом.","Вилучіть ланцюг із використання та віддайте його на професійну перевірку.","Підніміть вантаж лише наполовину.","Деформовані ланки ланцюга є видимими пошкодженнями, які можуть завадити безпечному використанню."],"b-einweiser":["Що важливо, коли видимість з екскаватора обмежена?","Частина будівлі закриває проїзд.","Відповідні візуальні заходи або інструкції та чітке спілкування.","Просто стежте за капотом.","Проїжджайте через зону повороту, незважаючи на те, що ви невидимі.","Якщо видимість обмежена, необхідно запобігти небезпеці за допомогою додаткових організаційних і технічних заходів."],"b-aushub":["Де можна зберігати виїмку біля котловану?","Край ями не повинен піддаватися додатковому ризику.","Складайте прямо на край, щоб під’їзні шляхи залишалися вільними.","Зберігайте на достатньо безпечній відстані та відповідно до специфікацій будівельного майданчика.","Встановіть на вільні опори без подальшого тестування.","Викопаний матеріал може загрожувати насипам і опорам через додаткові навантаження; Слід дотримуватися безпечних відстаней."],"b-personen":["Чи дозволяється людям залишатися в зоні повороту під час руху екскаватора?","Людина хоче вимірювати під час панорамування.","Так, якщо вона носить захисний шолом.","Так, якщо екскаватор повільно розгойдується.","Ні, небезпечна зона має бути вільна перед рухом.","Існує ризик серйозного защемлення та травм у зоні повороту; територія повинна бути вільною."],"b-ladung":["Як безпечно транспортувати матеріал за допомогою колісного навантажувача?","По двору треба водити наповнену лопату.","З відповідним низьким транспортним положенням і вільним шляхом.","З піднятою лопатою для кращої видимості.","З відкритими дверима та сильним кутом повороту.","Відповідне транспортне положення зменшує ризик перекидання та покращує стійкість під час руху."],"b-anbaupruefung":["Що ви перевіряєте після підключення навісного обладнання?","Приставили нову лопату.","Тільки чистота лакофарбового покриття.","Надійне замикання та функціонування відповідно до інструкції з експлуатації.","Тільки те, чи пристрій виглядає так само ззовні.","Неправильні замки швидкоз’ємних з’єднань можуть призвести до ненавмисного від’єднання навісного обладнання."],"b-einstieg":["Як безпечно потрапити в кабіну екскаватора?","Сходинки брудні після дощу.","Піднятися в кабіну через стрілу.","Сідайте на гусениці одним стрибком.","Використовуйте призначені сходинки та ручки та очищайте брудні сходинки.","Відповідні підйоми та безпечні точки утримування зменшують ризик ковзання та падіння."],"b-graben":["Стінка траншеї має тріщини та руйнується. Що правильно?","Ви працюєте прямо біля канави.","Припиніть роботи та попросіть відповідальних осіб закріпити котлован.","Просто проїдьте ближче до краю, щоб закрити канаву.","Поглибити траншею далі без захисту.","Тріщини та рухи ґрунту можуть свідчити про нестабільність і потребувати подальшої оцінки безпеки."],"b-betanken":["На що звертати увагу при заправці землерийної машини?","Бак майже порожній.","Захистіть двигун і джерела запалювання відповідно до інструкцій виробника та уникайте розливу.","Завжди заправляйте бензин або дизельне паливо в салоні.","Палити під час заправки, коли немає вітру.","Пожежа та небезпека навколишнього середовища під час роботи з паливом вимагають відповідних захисних заходів."],"b-laufwerk":["Чому слід регулярно перевіряти гусениці та ходову частину?","Ви помітили незвичайну вібрацію під час водіння.","Щоб машина рухалася швидше.","Оскільки пошкодження можуть вплинути на безпечне керування та стійкість.","Тому що завжди дозволяється робота без візуального огляду.","Пошкодження приводу може вплинути на маневреність, стабільність і безпечну роботу."],"b-einweisen":["Що потрібно для роботи поблизу громадського пішохідного руху?","Екскаватор працює прямо на краю тротуару.","Пішоходи повинні самостійно пересуватися зоною гойдалок.","Просто наклейте табличку на лопату.","Ефективно огородіть небезпечну зону та безпечно спрямуйте рух.","Треті особи не повинні входити в небезпечну зону землерийних машин; Необхідні відповідні бар'єри та маршрути руху."],"g2-fahrweg":["Попереду на дорозі розлита рідина. Як ти до цього ставишся?","Навантажувач проїжджав прямо по слизькій ділянці.","Припиніть керування автомобілем і закріпіть або видаліть небезпечне місце.","Проїдьте місце якомога швидше з піднятою вилкою.","Сподівайтеся на більш сухі шини та продовжуйте їздити без змін.","Забруднені дороги становлять загрозу для стійкості, тому їх необхідно належним чином закріпити перед тим, як їхати по них."],"g2-sichtladung":["Високий піддон закриває огляд вперед. Що правильно?","Вам потрібно їхати до місця зберігання, і ви не бачите маршруту.","Підніміть піддон, поки не побачите під ним.","Їдьте лише з використанням відповідних безпечних методів, таких як рух заднім ходом із вільним оглядом.","Ви все ще можете їздити по дорозі без покажчиків або чіткого огляду.","Напрямок руху і видимість повинні забезпечувати безпечне спостереження за маршрутом руху; Навантаження не повинні замінювати візуальний огляд."],"g2-fussgaengerstop":["Пішохід зупиняється прямо біля навантажувача. що ти робиш","Людина знаходиться в межах можливого діапазону руху та повороту.","Обганяйте пішохода, коротко прискорюючись.","Проїхати повз людину з піднятим вантажем.","Зупиніться та продовжуйте рух лише на безпечній відстані.","Люди повинні триматися подалі від небезпечної зони; У разі необхідності подорож необхідно перервати."],"g2-hubmast":["Ви помітили пошкоджену гідравлічну лінію на підйомній щоглі. Що стосується?","Гідравлічне масло витікає з агрегату.","Вивести навантажувач з експлуатації та повідомити про пошкодження.","Перевірте витік вручну під час підйому.","Піднімайте лише менші вантажі до закінчення зміни.","Гідравлічні пошкодження можуть призвести до неконтрольованих рухів; безпечне використання не гарантується до тесту."],"g2-lagerregal":["Ви хочете зберігати піддон на полиці. Що ви перевіряєте в першу чергу?","Рівень полиць високий, і вантажопідйомність має бути збережена.","Посуньте піддон на полицю якомога швидше.","Перевірте полицю, вагу навантаження та вільне місце для зберігання на придатність.","Оцініть загальну вагу виключно на основі кількості ящиків.","Полиці та транспортне обладнання повинні відповідати навантаженню та ситуації зберігання."],"g2-batterieschaden":["Батарея навантажувача пошкоджена зовні. Що правильно?","Перед завантаженням помічені тріщини або незвичайна рідина.","Заклейте пошкодження липкою стрічкою та негайно завантажте.","Дозвольте іншій особі заряджати акумулятор, не перевіряючи його.","Не заряджайте та не використовуйте та повідомте відповідальних спеціалістів.","Пошкоджені батареї становлять електричну та хімічну небезпеку та потребують професійної оцінки."],"g2-fahrerkabine":["Що стосується незакріплених предметів у зоні водія?","Інструменти лежать на підлозі поруч з педалями керування.","Приберіть предмети та тримайте робочу зону вільною.","Під час руху інструмент тримайте лише однією ногою.","Сховайте незакріплені частини під сидінням водія.","Незакріплені предмети можуть блокувати педалі та заважати безпечній експлуатації автомобіля."],"g2-uebergabe":["Ви приймаєте навантажувач після зміни зміни. Що це включає?","Востаннє транспортним засобом користувався колега.","Припустимо, що колега взяв на себе всі перевірки.","Проведіть необхідну перевірку та запитайте про відомі дефекти.","Почніть подорож, не дивлячись на машину.","Особа, яка приймає, повинна переконатися, що він знаходиться в безпечному стані перед використанням."],"g2-transportsicherung":["A tall object is loose on the pallet. як ти дієш","The load could tip forward when braking.","Тримайте вилку особливо високо, щоб вантаж залишався стабільним.","Just take the curves slowly, go straight faster.","Встановіть вантаж стабільно та зафіксуйте його від перекидання або падіння.","Незакріплені вантажі повинні бути стабілізовані перед транспортуванням, щоб гальмування та рух не спричинили їх падіння."],"g2-arbeitsende":["What is important with an unattended forklift?","You end your shift and leave the area.","Надійно припаркуйте автомобіль і захистіть його від відкочування та несанкціонованого використання.","Залиште ключ, щоб колеги знайшли машину.","Залиште вилку на рівні очей, щоб її було видно.","Безпечне паркування включає вантажопідйомність із заниженим вантажем і захист від переміщення та несанкціонованого введення в експлуатацію."],"g2-bremsweg":["Чому потрібно звертати особливу увагу на гальмівний шлях під навантаженням?","Навантажувач перевозить важкі вантажі через складський прохід.","Завжди гальмуйте пізніше з великим вантажем, ніж без вантажу.","Відрегулюйте швидкість відповідно до умов видимості, грунту та навантаження.","При гальмуванні різко піднімайте вантаж, щоб краще гальмувати.","Маса і стан дороги впливають на гальмівний шлях; адаптована швидкість є ключовою."],"g2-rampe":["What do you check before climbing a steep ramp?","The route may be too steep for the vehicle.","Їдьте по рампі на максимальній швидкості незалежно від ухилу.","Переїжджайте край рампи з піднятим вантажем.","Перевірте допустимий нахил і безпечний режим роботи з характеристик автомобіля.","Можна використовувати лише пандуси в межах передбачених експлуатаційних меж; Інструкції з експлуатації та контроль навантаження мають вирішальне значення."],"g2-zinke":["A pallet is wider than the fork distance. What needs to be taken into account?","You plan on taking on an unusually large load.","Відрегулюйте відстань між вилами та точки кріплення відповідно до навантаження.","Only use one tine if the load is too wide.","Підніміть вантаж під кутом, поки він не займе правильне положення.","Рівномірне та відповідне поглинання навантаження зменшує ковзання та перекидання."],"g2-betriebsanweisung":["Яку роль відіграє оперативне регулювання дорожнього руху?","На складі діють розмічені односторонні та пішохідні зони.","Для навантажувачів діють лише правила дорожнього руху загального користування.","Дотримуйтесь вказаних маршрутів та правил дорожнього руху.","Не звертайте уваги на маркування після завантаження автомобіля.","Маршрути компанії та правила безпеки захищають рух навантажувачів і людей, які ходять пішки."],"g2-nothalt":["Кермове керування незвично реагує під час руху. Що правильно?","Транспортним засобом більше не можна керувати як зазвичай.","Їдьте на вищих швидкостях, щоб рульове управління було чутливішим.","Компенсуйте похибку особливо великими відхиленнями керма.","Зупиніться в безпечному місці та перевірте автомобіль.","Порушене кермування загрожує безпечному керуванню; машина не повинна продовжувати безконтрольно працювати."],"g2-anschlagkette":["Ви хочете перемістити вільно висить вантаж за допомогою навантажувача. Що стосується?","На гаку під вилами повинен висіти вантаж.","Тільки з дозволеним пристроєм і відповідним вантажопідйомним обладнанням.","Підійде будь-який ланцюг, якщо вантаж невеликий.","Затисніть ланцюг безпосередньо між обома вилками.","Вільно висять вантажі змінюють стійкість; Потрібні схвалення виробника та відповідне обладнання."],"g2-rollenlast":["Циліндричний компонент лежить незакріпленим на піддоні. що ти робиш","Під час транспортування вантаж може скочуватися.","Підходьте до піддону особливо ривками.","Перед підйомом піддону зафіксуйте компонент від скочування.","Розташуйте зубці достатньо високо, щоб компонент не було видно.","Вантажі круглої форми або кочення вимагають надійного захисту від зміни положення."],"g2-pruefplakette":["Як дізнатися, чи можна використовувати навантажувач?","На машині є перевірочна наклейка.","Будь-яка наклейка завжди замінює щоденний візуальний огляд.","Відсутність кліренсу можна замінити обережною їздою.","На додаток до перевірки транспортного засобу необхідно враховувати дійсний статус випробування та схвалення експлуатації.","Періодичне тестування та щоденний контроль роботи виконують різні функції безпеки."],"g2-licht":["На складі раптово зникло освітлення. Що правильно?","Ви більше не можете безпечно бачити перешкоди на шляху.","Припиніть рух, поки не буде гарантована безпечна видимість.","Збільште швидкість, щоб залишити темну зону.","Продовжуйте рух із піднятими вилами без візуального огляду.","Маршрут, який не можна безпечно пропустити, не можна проїжджати без ефективних заходів безпеки."],"g2-ueberhang":["Вантаж виходить далеко за край вилки. Що ти перевіряєш?","Ви хочете транспортувати піддон через вузькі ворота.","Компенсуйте бічну проекцію швидким вигином.","Оцініть кліренс, стійкість і допустиме навантаження перед поїздкою.","Ведіть вантаж на максимальній швидкості незалежно від його форми.","Звиси збільшують ризики зіткнень і можуть змінити стабільність і необхідний простір для руху."],"g2-wartungsbereich":["Перед зоною обслуговування є шлагбауми. як ти себе ведеш","Ваш звичайний маршрут тимчасово закрито.","Ненадовго перемістіть шлагбаум і проїдьте непомітно.","Проїжджайте прямо через робочу зону під навантаженням.","Слідкуйте за закриттям та оберіть затверджений альтернативний маршрут.","Забороняється входити в оточені зони або проїжджати через них без дозволу."],"g2-bremsprobe":["Коли має сенс перевірка роботи робочого гальма?","Ви готуєте навантажувач перед роботою.","У рамках необхідної перевірки перед використанням.","Виконуйте лише після серйозної аварії.","Тільки якщо вантажівка вже набрала велику швидкість.","Працездатність засобів безпеки перевіряється перед використанням."],"g2-fahrzeuganhaenger":["Ви хочете тягнути причіп навантажувачем. Що потрібно?","Компанія планує перевезення з навісним вантажем.","Прив’яжіть кожен причіп до вил без перевірки.","Дотримуйтеся схвалення виробника, відповідного з’єднання та допустимого навантаження на розтяг.","Просто підвищте тиск у шинах і рушайте.","Безпечна експлуатація поїзда можлива лише в межах технічних специфікацій і за наявності відповідного сполучення."],"g2-rueckfahrt":["Що важливо при русі заднім ходом на навантажувачі?","У складському проході заплутана зона.","Завжди дивіться тільки в дзеркало заднього виду, незалежно від оточення.","Їдьте без видимості до тих пір, поки клаксон натиснутий один раз.","Безпечно спостерігайте за маршрутом і територією людей і, якщо необхідно, проінструктуйте їх.","Рух заднім ходом вимагає чіткого огляду або ефективних додаткових заходів безпеки."],"g2-lastentnahme":["Ви дістаєте піддон з високої полиці. Що правильно?","Палітра може бути не відцентрована.","Перед опусканням безпечно підніміть вантаж і стабілізуйте його.","Дозвольте піддону похитнутися вбік, коли ви його витягуєте.","Перевірте, чи не пошкоджено під піднятим піддоном.","Контрольований підйом і опускання запобігає падінню вантажів і небезпечним рухам."],"h2-absenkweg":["Чому площа під підйомною платформою має залишатися вільною?","Кошик опускається, а під нього кладуться матеріали.","Притисніть матеріали кошиком.","Слідкуйте лише за зоною ніг оператора.","Уникайте ризику защемлення та зіткнення під час опускання.","У зоні спуску не повинно бути людей або перешкод, які можуть бути затиснуті."],"h2-transporthoehe":["Як перемістити мобільну сцену над низьким проходом?","Кліренс нижчий, ніж у подовженої стріли.","Розмістіть платформу у відповідному транспортному положенні відповідно до інструкції з експлуатації.","Залиште стрілу витягнутою та рухайтеся під стелею.","Притисніть кошик до дверної рами.","Для транспортування загальна висота та транспортне положення повинні відповідати специфікаціям виробника та проходу."],"h2-bodenoeffnung":["У підлозі біля сцени є незакріплений отвір. Як ви реагуєте?","Біля отвору розташовується провідна або опорна точка.","Поставте опору прямо на край отвору.","Змініть місце встановлення або зверніться до професійної перевірки вантажопідйомності та кріплення.","Накрийте небезпечну точку тільки картонною коробкою.","Отвори та крайові ділянки можуть вийти з ладу під впливом опорних навантажень, і це необхідно враховувати."],"h2-rettungsperson":["Чому друга особа повинна бути знайома з процедурою порятунку?","Оператор може стати непрацездатним у верхній частині.","Так що робота в кошику взагалі може проходити без охорони.","Щоб сцена могла працювати швидше, ніж дозволено.","Щоб у надзвичайних ситуаціях можна було розпочати безпечне порятунок.","Концепція порятунку повинна враховувати наземну допомогу в разі аварії або надзвичайної ситуації."],"h2-werkzeugabwurf":["Що стосується інструментів на великій висоті?","Незакріплений інструмент може впасти через край кошика.","Закріпіть інструменти так, щоб вони нікому не загрожували та не падали.","Просто помістіть інструменти на поручні, щоб зменшити навантаження.","При необхідності викидайте інструменти з кошика.","Падаючі предмети становлять небезпеку для людей, які знаходяться внизу; Матеріал необхідно зберігати безпечно."],"h2-trittstufe":["Ящик повинен служити додатковим місцем для стояння в кошику. Що правильно?","Інакше ви ледь доїдете до робочого місця.","Поставте ящик на поручні і залізьте на нього.","Не піднімайтеся на імпровізовані підвищення; Використовуйте відповідне робоче обладнання.","Навмисно завантажуйте кошик понад дозволену висоту.","Імпровізовані підйоми погіршують запланований захист від падіння і не допускаються."],"h2-lastverteilen":["На що ви звертаєте увагу, коли в робочому кошику кілька людей?","Двоє людей працюють у кошику з важкими інструментами.","Оцініть навантаження виключно на основі розміру інструменту.","Зберігайте важкі інструменти безпосередньо на захисних поручнях.","Не перевищуйте допустиме завантаження кошика, включаючи людей та інструменти.","Дозволена вантажопідйомність включає всіх людей, матеріали та інструменти в кошику."],"h2-abstuetzplatte":["Коли розглядаються додаткові прокладки для опор?","Монтажна підлога може витримувати лише обмежене навантаження.","Якщо це необхідно для безпечного розподілу навантаження відповідно до специфікацій.","Щоб розташувати опори якомога ближче до краю котловану.","Щоб використовувати більший діапазон без інформації про виробника.","Для безпечної підтримки сил потрібна достатня площа контакту."],"h2-baugrube":["Підмосток повинен розташовуватися безпосередньо біля краю котловану. Що ти перевіряєш?","Ґрунт міг проступити вбік через котлован.","Протягніть опори в котлован.","Забезпечте достатню безпечну відстань і несучу здатність підґрунтя.","Компенсуйте ризик, лише повільно піднімаючи кошик.","Котловани можуть вплинути на стійкість через схил і провал грунту."],"h2-witterung":["Ожеледь утворюється під час використання. як ти дієш","Поверхні керування та робоча зона стають гладкими.","Підніміть сцену, щоб уникнути снігу та льоду.","Ігноруйте попередження, поки платформа освітлена.","Перервіть роботу та переоцініть умови роботи відповідно до інструкції з експлуатації.","Зміни погоди можуть змінити відповідальність, працездатність і безпечні межі використання."],"h2-aufbaukontakt":["Сталева конструкція обмежує шлях кошика. Що важливо?","Під час підйому існує ризик защемлення між кошиком і переноскою.","Плануйте рухи так, щоб ваше тіло та кошик не потрапили в пастку.","Зробіть подорож швидше, щоб кошик швидше пройшов повз.","Відсуньте конструкцію з кошиком в сторону.","Точки защемлення між платформою та навколишнім середовищем вимагають ретельного спостереження та контрольованого руху."],"h2-sicherheitsabstand":["Коли небезпечна зона сцени повинна бути огороджена?","Під ділянкою проходить маршрут громадського транспорту.","Тільки якщо предмет вже впав.","Якщо рух або падіння предметів можуть загрожувати третім особам.","Ніколи, оскільки робочий кошик практично запобігає всім небезпекам.","Територія під сценою та біля неї повинна бути захищена від передбачуваних небезпек."],"h2-korbtor":["Що стосується вхідних дверей робочого кошика?","Ви вже на робочій висоті.","Залиште двері відкритими, щоб швидше вийти.","Прив’яжіть двері назавжди відкритими мотузкою.","Тримайте двері закритими відповідно до запірного механізму.","Надані замки є частиною захисних заходів проти падіння з робочої клітки."],"h2-energieleitung":["Що застосовується, якщо повітряну лінію не безпечно вимкнути?","Ви працюєте з автовишкою біля них.","Забезпечте вказані безпечні відстані та необхідні захисні заходи.","Перемістіть кошик прямо перед лінією, доки його не торкнеться.","Довіртеся пластиковим шинам і працюйте без зазорів.","Електричні спалахи також можливі без прямого контакту; Необхідні безпечні відстані."],"h2-schwanken":["Робочий кошик починає незвично сильно розгойдуватися. Що правильно?","Рух більше не контролюється.","Неконтрольоване перенастроювання швидкими зустрічними рухами.","Зупиніть рух і перевірте причину або умови роботи.","Додайте додаткових людей у ​​кошик, щоб зробити його важчим.","Незвична вібрація може свідчити про невідповідні умови роботи або несправність."],"h2-ladegeraet":["Пошкоджено зарядний кабель для електричного столика. що ти робиш","При підключенні видно пошкоджену ізоляцію.","Торкатися пошкодження мокрими рукавичками.","Втисніть вилку в розетку якомога сильніше.","Не починайте процес заряджання та зверніться до професійної перевірки кабелю.","Пошкоджена електропроводка створює ризик ураження електричним струмом і пожежі."],"h2-gelaenderanbau":["Чи можете ви самостійно зняти перила, щоб підійти ближче?","Компонент запобігає наближенню людей до місця проведення робіт.","Не змінюйте та не знімайте захисні пристрої самостійно.","Після підйому відкрутіть перила і встановіть їх пізніше.","Продовжуйте працювати без перил, поки хтось стоїть поруч.","Структурні захисні пристрої не можуть бути змінені без дозволених специфікацій і заходів щодо безпечної заміни."],"h2-lastkran":["Чи можна платформу використовувати як кран для підйому вантажу?","Матеріал слід транспортувати вільно підвішеним поруч із робочим кошиком.","Щоразу, коли вага менша за вагу вашого тіла.","Тільки якщо виробник і обладнання прямо дозволяють таке спеціальне використання.","Просто прикріпіть гачок до перил і підніміть матеріал.","Підйомники не призначені автоматично для роботи краном або додатковими підвішеними вантажами."],"h2-arbeitsvorbereitung":["Що входить у підготовку до нового місця?","Ви ще не знаєте будівельного майданчика.","Просто оцініть відстань до найближчої стоянки.","Незалежно від оточення, негайно повністю розширте його.","Оцініть небезпеки, ґрунт, маршрути руху, придатність рятувального обладнання та обладнання.","Оцінка ризику, пов’язана з місцем розташування, є необхідною умовою безпечних умов експлуатації."],"h2-kabelschlaufe":["Поперек сцени пролягає кабель живлення. Що правильно?","Кабель може затиснутися під час руху.","Очистіть дорогу та захистіть електричні кабелі від пошкоджень.","Використовуйте трос з колесами як поріг дороги.","Підніміть кошик, не перевіряючи площу підлоги.","Кабелі, на які наїхали або роздавили, можуть спричинити електричні та механічні небезпеки."],"h2-leitungsnaehe":["Хто роз'яснює захисні заходи на електричній системі?","Платформа повинна працювати поблизу живого обладнання.","Людина в кошику вирішує виключно на око.","Залучати відповідальні органи та здійснювати скоординовані захисні заходи.","Відстань буде визначено лише після початку робіт.","Робота поблизу електричних систем вимагає спланованих і скоординованих заходів захисту."],"h2-funkkommunikation":["Чому сигнали між підлогою та кошиком мають бути чіткими?","Людина на землі допомагає маневрувати.","Щоб кілька людей могли давати суперечливі вказівки одночасно.","Щоб аварійне опускання можна було спробувати без інструкцій.","Так що рухи здійснюються тільки після чіткого спілкування.","Чітка комунікація зменшує неправильні рухи та зіткнення під час маневрування."],"h2-neuebedienung":["Ви переходите на інший тип сцени. Що потрібно?","Істотно відрізняються робочі функції.","Інструкція для конкретного пристрою перед самостійним використанням.","Просто читання логотипу компанії на пристрої.","Тест-драйв з уже розширеним кошиком без інструкцій.","Сама по собі кваліфікація не замінює навчання конкретному типу пристрою."],"h2-steckanschluss":["Що потрібно перевірити перед підключенням зарядного пристрою?","Електричну підйомну платформу потрібно зарядити.","Використовуйте будь-яку розетку незалежно від стану та запобіжника.","Перевірте правильне підключення та непошкоджений кабель відповідно до інструкцій виробника.","Регулярно від’єднуйте вилку від мережі під час заряджання.","Відповідні та справні електричні з’єднання захищають від ураження електричним струмом і пожежі."],"h2-absperrpersonal":["Під час вантажопідйомних робіт людина потрапляє в огороджену зону. що ти робиш","Ви можете побачити людину прямо під робочим кошиком.","Продовжуйте рух, якщо на особі захисний шолом.","Киньте інструмент у їхньому напрямку як попереджувальний сигнал.","Припиніть небезпечний рух і звільніть територію.","Бар'єр не замінює спостереження за небезпечною зоною під час експлуатації."],"k2-arbeitsplanung":["Що необхідно включити в підготовку до роботи перед роботою крана?","Вантаж, місце та маршрут транспортування ще не узгоджені.","Першим підніміть найважчий вантаж без подальшого планування.","Позначте лише найкоротший маршрут на підлозі холу.","Заздалегідь уточніть вантажопідйомність, стропи, шлях вантажу та небезпечну зону.","Запланований рух крана вимагає належного транспортування вантажу, безпечних маршрутів і скоординованих захисних заходів."],"k2-hakenposition":["Як розташовується гак крана над вантажем перед підйомом?","Точки кріплення знаходяться під краном.","Максимально вертикально над центром ваги відповідно до упору.","Зміщений далеко вбік, щоб вантаж швидше розгойдувався.","У будь-якому випадку на зовнішньому краю вантажу, незалежно від центру ваги.","Вертикальне застосування сили та відповідні опорні точки зменшують бічні рухи та неконтрольовані рухи."],"k2-hakengabel":["Вантажний гак демонструє помітну деформацію. Що стосується?","Гачок виглядає зігнутим у порівнянні зі своїм звичайним станом.","Зігніть деформацію назад наступним навантаженням.","Зупиніть роботу крана та попросіть фахівця перевірити гак.","Приєднуйте лише легкі вантажі та продовжуйте роботу.","Деформація може вплинути на безпеку гачка; несанкціоноване подальше використання заборонено."],"k2-zugueberlast":["Тягар важчий, ніж передбачалося спочатку. що ти робиш","Під час підготовки з’являється нова інформація про вагу.","Замініть запас безпеки швидшим підйомом.","Ігноруйте вагу вантажу, прикріпивши його до іншої точки.","Визначте фактичне навантаження та ще раз перевірте межі навантаження.","Для безпечного підйому потрібні достовірні дані про навантаження та дотримання всіх відповідних вантажопідйомностей."],"k2-arbeitskorb":["Чи може звичайний гак крана легко перевозити людей?","Людина хоче потрапити на високу роботу.","Ні, пасажирські перевезення потребують дозволених спеціальних засобів і заходів.","Так, якщо людина тримається за мотузку слінгу.","Так, як тільки гребок здійснюється особливо повільно.","Перевезення людей дозволяється лише за особливих умов, передбачених для цієї мети."],"k2-bruecke":["Мостовий кран рухається по спільній доріжці. Що важливо?","Працівники залишаються під транспортним маршрутом.","Їхати з вантажем прямо над головами співробітників.","Ефективно зберігайте маршрут вантажу та зону руху вільними та безпечними.","Використовуйте лише попереджувальний гудок замість подальших заходів.","Люди з групи ризику не повинні перебувати під підвішеними вантажами або на шляху транспортування."],"k2-zweitekrane":["Два крани працюють у зоні перекриття. Що необхідно?","Стріли або вантажі можуть зіткнутися один з одним.","Обидва кранівники працюють одночасно без попередньої домовленості.","Рухи навмисно прискорені, щоб уникнути перехресть.","Координувати дії та вживати відповідних заходів для запобігання взаємним загрозам.","Робочі зони, що перекриваються, потребують узгодженої організації роботи та відповідних заходів безпеки."],"k2-pruefbuch":["Яке значення має обов'язковий періодичний огляд крана?","Машина регулярно використовується в експлуатації.","Він доповнює оперативний контроль призначеною експертизою.","Він назавжди замінює будь-який візуальний огляд перед початком роботи.","Це потрібно лише після аварії.","Періодичні перевірки та поточні оперативні контролю мають різні завдання."],"k2-absetzflaeche":["Передбачувана площа розміщення нерівна. як ти дієш","При розміщенні вантаж може перекинутися.","Покладіть вантаж на один кут і дайте йому висіти без змін.","Підготуйте відповідну, несучу та стійку основу чи поверхню.","Помістіть одну людину під вантаж під час опускання.","Місця розміщення повинні безпечно підтримувати вантаж і запобігати небезпечним перекиданням або перекочуванню."],"k2-anfahrbereich":["Перед тим, як кран почне рухатися, в зоні руху знаходиться одна людина. що ти робиш","Трасу перекриває людина.","Відштовхніть людину за допомогою короткого тест-драйву.","Рухайтесь, використовуючи лише кінцевий вимикач без візуального огляду.","Починайте рух лише тоді, коли небезпечна зона вільна та безпечна.","Їзда та поворотні рухи не повинні загрожувати людям."],"k2-schlaffseil":["Чому підйомний трос не повинен неконтрольовано провисати, коли його опускають?","Вантаж стоїть, гак опускається далі.","Щоб мотузка і гачки не заклинили і не піддалися неконтрольованому навантаженню.","Щоб потім вантаж можна було тягнути збоку за мотузку.","Щоб стропи самі від'єднувалися від гачка.","Неконтрольована прокладка кабелю може призвести до заплутування та небезпечного переміщення вантажу."],"k2-pendel":["Вантаж, що транспортується, починає розгойдуватися. Що правильно?","Вантаж зміщується вбік більше, ніж планувалося.","Компенсуйте швидкими зустрічними рухами та повною швидкістю.","Зменште контрольовані рухи та спокійну поїздку без людей у ​​небезпечній зоні.","Тримайте вантаж, що хитається, голими руками.","Коливальні навантаження можуть впливати на людей і об'єкти; спокійні рухи знижують ризик."],"k2-funkakku":["Радіоуправління крана має слабкий акумулятор. Що стосується?","З'єднання може розірватися під час підйому.","Швидко піднімайте вантаж, поки не вийде з ладу керування.","Якщо з’єднання втрачено, перемістіть вантаж, потягнувши за строп.","Перед використанням переконайтеся в надійному керуючому з’єднанні.","Надійний контроль і зв'язок є передумовами для контрольованих рухів крана."],"k2-mehrereanschlaeger":["Двоє людей одночасно подають різні сигнали кранівнику. Що правильно?","Знаки суперечать один одному.","Перервати рух і чітко визначити відповідальність.","Віддайте перевагу знаку людини, що знаходиться далі.","Продовжуйте рух відповідно до власних відчуттів.","Машиністам кранів потрібна чітка та недвозначна комунікація, особливо коли маршрути вантажу заплутані."],"k2-endabschaltung":["Чому не можна зловживати кінцевим вимикачем як звичайним обмеженням ходу?","Вантаж часто переміщується на максимальну відстань підйому.","Кінцеві вимикачі зазвичай дозволяють швидше піднімати без видимості.","Кінцеві вимикачі є пристроями безпеки і не замінюють контрольованої роботи.","При кожному ударі їх потрібно бити якомога сильніше.","Запобіжні пристрої служать для захисту від небезпек, і ними не можна зловживати за планом."],"k2-wetterbeobachtung":["Вітер значно посилюється при великому навантаженні на площу. Що потрібно?","Велика площа компонентів діє як вітрило.","Завжди піднімайте вантаж вище, щоб вітер мав менший вплив.","Замініть стропи на більш тонкі.","Оцініть вітрові та робочі межі та відрегулюйте підйом, якщо необхідно.","Вітер може створювати значні додаткові сили та маятникові рухи, особливо при навантаженні великої площі."],"k2-ortswechsel":["Що важливо при переміщенні автокрана на нове місце?","Змінюються грунтові та опорні умови.","Перевірте розташування підставки та опору, перш ніж знову брати вантаж.","Застосуйте налаштування з попереднього розташування без перевірки.","Під час підйому відрегулюйте опору.","Кожне місце установки може мати різні умови навантаження на грунт і опору."],"k2-betriebsbereich":["Через вулицю має працювати кран. Що потрібно уточнити?","У небезпечну зону можуть потрапити треті особи.","Охороняйте дорогу лише звуковим сигналом.","Необхідні блокування, голосування та заходи охорони перед хабом.","Підніміть вантаж над транспортними засобами якомога швидше, не закріплюючи його.","Безпечна маршрутизація руху запобігає надмірному ризику для третіх сторін через вантажі та рух крана."],"k2-hochheben":["Після пробного підйому вантаж висить явно криво. Що правильно?","Фокус, очевидно, був неправильно оцінений.","Продовжуйте піднімати, щоб дисбаланс виправився сам.","Попросіть одну людину тягнути нахилений вантаж.","Надійно встановіть вантаж і знову перевірте кріплення та центр ваги.","Тестовий підйомник використовується для виявлення неправильного кріплення та нестабільного положення вантажу перед транспортуванням."],"k2-schwebelast":["Чи можна залишити піднятий вантаж висіти без нагляду?","Зміна закінчується, але навантаження ще на гачку.","Ні, безпечно опустіть вантаж і належним чином закріпіть кран.","Так, якщо кран заблокований від відведення.","Так, якщо на землі є попереджувальний знак.","В принципі, підвішені вантажі не можна залишати без нагляду."],"k2-mitnahme":["Колега хоче покататися на вантажі крана. Що стосується?","Вантаж слід транспортувати на більш високу точку.","Їзда дозволена, якщо колега носить шолом.","Людей не можна перевозити або прикріплювати до звичайних вантажів.","Поїздка завжди дозволена, якщо машиніст крана знає колегу.","Перевезення людей разом із вантажами створює значні ризики падіння та розчавлення."],"k2-warnsignal":["На крані вийшла з ладу система оповіщення про роботу. Що правильно?","Більше неможливо надати попередження перед початком руху.","Ігноруйте систему, коли двигун працює.","Назавжди замініть попередження, торкнувшись корпусу.","Повідомте про помилку, пов’язану з безпекою, і перервіть роботу відповідно до інструкцій.","Необхідні сигнальні пристрої повинні бути справними, щоб люди були захищені вчасно."],"k2-schneekante":["Автокран потрібно підтримувати на мерзлій, нерівній землі. Що стосується?","При відтаванні грунт може втратити несучу здатність.","Оцініть вантажопідйомність і опорну ситуацію за реальних умов.","Мерзлий грунт завжди має будь-яку несучу здатність.","Ставте опори тільки на невеликі камені.","Температура, вологість і структура грунту впливають на несучу здатність місць розташування кранів."],"k2-laufkatze":["Візок рухається назустріч перешкоді. як ти дієш","У зоні проїзду є об'єкт.","Повільно відштовхніть предмет разом з вантажем.","Вчасно зупиніть рух і безпечно усуньте перешкоду.","Проїхати повз перешкоду на підвищеній швидкості.","Рухи крана повинні бути спрямовані таким чином, щоб не відбувалося зіткнення з перешкодами."],"k2-anschlagaufnahme":["Брати вантаж слід за допомогою непризначеного вушка. Що правильно?","Вушко могло бути призначене лише для кріплення кришки.","Кожна петля підходить для повного навантаження крана.","Завантажувати вушко можна лише двома людьми одночасно.","Перевірте вантажопідйомність і придатність точки кріплення перед використанням.","Не кожна існуюча петля є стабільною точкою кріплення для кранових вантажів."],"l2-seilbruch":["Трос показує кілька обірваних окремих дротів. Що правильно?","Точки розриву знаходяться в зоні несучого каната.","Не продовжуйте використовувати вантажопідйомне обладнання та віддайте його професійній оцінці.","Загніть кінці дроту назад голими руками.","Продовжуйте використовувати мотузку, якщо вантаж особливо легкий.","Обриви дротів можуть бути критерієм викиду; Пошкоджені канати повинні бути оцінені професійно."],"l2-schaekel":["Що має вирішальне значення при використанні дужки?","Скоба з'єднує строп і вантаж.","Замініть болт будь-яким цвяхом.","Перевірте відповідну вантажопідйомність, непошкоджений стан і правильні болти.","Оцініть вантажопідйомність за кольором.","Скоби повинні бути відповідного розміру, використовуватися повністю та в передбаченому напрямку завантаження."],"l2-tragfaehigkeit":["Що потрібно враховувати при використанні кількох ниток?","Пасма йдуть під кутом до вертикалі.","Просто складіть вантажопідйомність кожної нитки за бажанням.","Вішайте вантаж тільки на найлегше пасмо.","Враховуйте несучу здатність всього типу анкера і кутника.","На допустиме навантаження істотно впливає кут нахилу і ефективна кількість пасом."],"l2-schweissnaht":["Чи можна приварити до вантажу імпровізовану точку кріплення?","Немає відповідних визначених пунктів прийому вантажу.","Використовуйте лише належним чином розроблені та схвалені точки кріплення.","Досить будь-якого зварного шва без перевірки.","Вставте гачок в отвір у металевому листі.","Точки кріплення мають бути придатними для сил, залучених до підйому."],"l2-einseitig":["Вантаж значно важчий з одного боку. Як ти до цього ставишся?","Центр тяжіння знаходиться поза геометричним центром.","Залиште всі пасма однакової довжини незалежно від центру ваги.","Визначте центр ваги та відрегулюйте положення відповідно.","Спочатку підніміть вантаж на повну висоту.","Якщо центр ваги зміщений від центру, вантажі можуть несподівано перекинутися або окремі нитки можуть бути перевантажені."],"l2-kettenriss":["Що стосується ланцюгової стропи з видимими тріщинами?","В одній із ланок ланцюга є тріщина.","Позначте тріщину фарбою і підніміть її без змін.","Обмотайте ланку дротом і використовуйте її повторно.","Негайно зніміть ланцюг і повідомте відповідальну особу.","Тріщини в несучих ланках ланцюга є пошкодженням, важливим для безпеки, і вимагає виведення з експлуатації."],"l2-lastfuehrung":["Як нести великий вантаж, якщо є ризик повороту?","Під час підйому вантаж може розхитуватися вбік.","Використовуйте відповідні засоби наведення та дотримуйтеся безпечної відстані.","Тримайте вантаж прямо між руками під час руху.","Підступіть під вантаж і вирівняйте його знизу.","Направлення вантажу не повинно призводити до того, щоб руки або тіла потрапляли в небезпечну зону."],"l2-schnueren":["Що важливо при кріпленні шнурків?","Строп ведеться навколо компонента.","Припустимо, що вантажопідйомність буде такою ж, як і будь-який інший тип анкера.","Слідкуйте за придатністю типу кріплення та допустимим навантаженням відповідно до маркування.","Стягніть строп до будь-якої міри без перевірки.","Тип кріплення шнурка може змінювати допустиму вантажопідйомність і повинен використовуватися правильно."],"l2-winkelmesser":["Чому не можна ігнорувати плоский кут пасма?","Дві стропи проходять майже горизонтально до вантажу.","Плоский кут автоматично робить пасмо міцніше.","Навантаження завжди розподіляється однаково незалежно від кута.","Високі зусилля пасма можуть перевищувати допустиме навантаження.","Зі збільшенням кута до вертикалі зростають напруги на нитках."],"l2-heisse-last":["Що потрібно перевірити на гаряче навантаження?","Сталева частина була нещодавно термічно оброблена.","Дотримуйтеся температурних обмежень строп та відповідного вибору.","Кожен текстильний слінг витримує будь-яку температуру.","Маркування не має значення, коли гаряче.","Температура може впливати на допустиму вантажопідйомність строп."],"l2-abstand":["Чи можете ви підкласти пальці під вантаж, коли його кладете?","Вантаж повинен припадати на поверхню з точністю до міліметра.","Так, якщо ви носите робочі рукавички.","Ні, дотримуйтеся дистанції та використовуйте відповідні засоби допомоги.","Так, якщо рух крана особливо повільний.","Частини тіла між вантажем і основою можуть затиснутись."],"l2-verbindung":["З'єднувальна ланка ланцюга стропа не замикається. Що стосується?","Застібка відсутня.","Використовуйте засув без замка, коли ніхто не дивиться.","Заклейте елемент скотчем.","Не вдаряйте, доки застібка не буде належним чином закріплена.","З'єднувальні елементи повинні бути закріплені повністю і відповідно до їх конструкції."],"l2-lasthaken":["Що перевіряють, коли висять на гак крана?","У гачок слід завести кілька строп.","Переконайтеся в надійній посадці та придатності гаків і підвіски.","Надіньте стропи на кінчик гачка.","Замініть гаковий замок кабельною стяжкою.","Сила повинна застосовуватися за призначенням у визначених місцях."],"l2-fasern":["Підйомний ремінь показує сильну шорсткість і пошкодження волокна. Що правильно?","Опорні волокна помітно пошкоджені.","Закрийте пошкодження іншим вузлом.","Від’єднайте підйомний ремінь і віддайте його на перевірку спеціалісту.","Тоді піднімайте вантаж швидше.","Пошкоджені несучі волокна можуть значно знизити несучу здатність підйомного ременя."],"l2-anheben":["Що стосується відразу після першого сантиметра підйому?","Вантаж просто піднімається зі своєї основи.","Витягніть вантаж на повну висоту без контролю.","Перевірити під вантажем, чи натягнуті стропи.","Перевірте положення зупинки, баланс і поведінку руху.","Контрольований тестовий підйом робить можливу нестабільність видимою перед подальшим транспортуванням."],"l2-lastgewichte":["Вага вантажу невідома. Що правильно?","Компонент не має маркування ваги.","Перш ніж вибрати стропи, визначте вагу, яку можна навантажувати.","Оцініть вагу, виходячи з кольору вантажу.","Використовуйте будь-який слінг подвійної довжини.","Без відомої або надійно визначеної ваги придатність строп не може бути перевірена з упевненістю."],"l2-lose-teile":["На вантажі, який потрібно підняти, є незакріплені інструменти. що ти робиш","Під час підйому інструменти можуть впасти.","Під час водіння тримайте інструменти однією рукою.","Перед підйомом зніміть або ефективно закріпіть незакріплені предмети.","Піднімайте вантаж трохи швидше, щоб нічого не зісковзнуло.","Незакріплені предмети можуть впасти та створити небезпеку для людей у ​​цьому місці."],"l2-wind":["При сильному вітрі кріпиться великий вантаж. Що стосується?","Компонент пропонує вітру велику площу поверхні для атаки.","Піднімайте вантаж, не враховуючи похитування.","Додаткові люди повинні тримати вантаж безпосередньо.","Оцініть умови вітру та утримайтеся від підйому, якщо ситуація небезпечна.","Сила вітру може вплинути на напрямок вантажу та стійкість під час транспортування."],"l2-unterlage":["Чому під час відлучення важливі відповідні документи?","Круглий вантаж покотився б по землі.","Надійно покладіть вантаж і, якщо необхідно, зафіксуйте його від скочування.","Залиште вантаж стояти прямо на стропах.","Проштовхуйте документи під вантаж лише після того, як вони були покладені.","Відповідні опори запобігають перекиданню та небажаним рухам під час посадки."],"l2-transportweg":["Що потрібно узгодити перед транспортуванням вантажу?","Вантаж переміщується по кількох робочих зонах.","Просто очікувана тривалість хабу.","Безпечний шлях вантажу, зв'язок і необхідні бар'єри.","Дорогу під вантажем повинен показувати один.","Транспортування вантажів вимагає безпечних маршрутів руху та чіткої координації."],"l2-schutzschlauch":["На що звернути увагу при використанні строп із захисним шлангом?","Смуга прилягає до нерівного краю.","Будь-яка тонка тканинна тканина замінює відповідний захист країв.","Захисний шланг знімає будь-які допустимі межі навантаження.","Виберіть захисне спорядження відповідно до придатності та вимог застосування.","Захисні засоби повинні відповідати матеріалу, кромці та передбачуваному навантаженню."],"l2-reinigung":["Підйомний ремінь був забруднений невідомою хімікатом. Що правильно?","Стрічку вже неможливо чітко оцінити.","Припиніть використання та уточніть сумісність або стан професійно.","Очистіть будь-яким розчинником і негайно продовжуйте підйом.","Ігноруйте хімічну речовину, поки стрічка суха.","Хімічні речовини можуть вплинути на міцність текстильних строп."],"l2-aufhaengung":["Що ви перевіряєте на наявність кількох ниток на ланці підвіски?","Дві нитки поміщаються разом у суспензію.","Пасмо може просуватися до кінчика гачка за бажанням.","Всі сполучні елементи повинні бути придатними і розташованими за призначенням.","Кільце з тріщиною можна використовувати для невеликих навантажень.","Упор і сполучні елементи повинні бути несучими і правильно розташованими."],"l2-einweiserrolle":["Що має місце, якщо зловмисник і кранівник не мають прямої видимості?","Носій закриває огляд точки висадки.","Координація викликом кількох людей без відповідальності.","Переміщуйте вантаж на основі шуму без інструкцій.","Організуйте чітке, безпечне спілкування та припиніть його, якщо воно незрозуміле.","Відсутність видимості має бути компенсована ефективною координацією та безпечним зв’язком."],"l2-ausserbetrieb":["Пошкоджену стропу розібрали. Що ще важливо?","Він залишається у вільному доступі разом із готовими до використання ресурсами.","Забезпечте захист від подальшого випадкового використання та повідомте відповідальну особу.","Повернути продукт без маркування в інвентар.","Використовуйте його знову, лише коли перевозите особливо легкий вантаж.","Викинуті стропи перед подальшим використанням необхідно надійно захистити."],"b2-schwenkradius":["Чому задній радіус повороту екскаватора є критичним?","Хвіст рухається по обмеженій робочій зоні.","Надбудова, що хитається, може зачепити третіх осіб.","Радіус повороту не впливає на людей поруч з машиною.","Задня частина завжди рухається тільки в напрямку руху.","Під час повороту позаду машини також виникає небезпечна зона."],"b2-verkehrseinweiser":["Як забезпечується рух за кермом, коли видимість закрита?","Екскаватор повинен маневрувати за перешкодою.","Їхати, не бачачи сигналів сигналістів.","Якщо необхідно, організуйте відповідний інструктаж із чітким спілкуванням.","Забезпечте рух заднім ходом лише одним сигналом.","Заплутані маршрути вимагають ефективних заходів для запобігання зіткненням і захопленням."],"b2-standplatz":["Що стосується стійки екскаватора на схилі?","Підлога має нахил і може бути слизькою.","Машина може висуватися на будь-яку межу під будь-яким нахилом.","Завжди встановлюйте екскаватор на пухкий шар землі.","Перед використанням перевірте стабільність і робочі межі машини.","Значний вплив на стійкість мають ухил схилу та підґрунтя."],"b2-oberleitung":["Чому необхідно планувати відстань стріли від ліній електропередач?","Під час повороту стріла може наближатися до кабелю.","Електричний спалах також можливий без прямого контакту.","Лише відро може проводити електрику, а не стріла.","З сухим ґрунтом кожна відстань автоматично безпечна.","Перед підходом до електричних систем необхідно уточнити межі використання та захисні відстані."],"b2-fremdperson":["Перехожий заходить на будівельний майданчик у зону панорамування. Що правильно?","Людина раптово стоїть біля ковша екскаватора.","Підніміть лопату вгору і розмахніть нею над людиною.","Негайно припиніть рух і звільніть територію.","Просто продовжуйте спостерігати за людиною з бічного вікна.","Люди в небезпечній зоні не повинні загрожувати робочим рухам."],"b2-parkstellung":["Як закріплюється землерийна машина після закінчення роботи?","На будівельному майданчику екскаватор залишається без нагляду.","Залиште ложку на висоті голови.","Нехай двигун працює без нагляду.","Покладіть робоче обладнання, закріпіть машину та запобігайте несанкціонованому використанню.","Належне паркування зменшує випадкові переміщення та несанкціонований доступ."],"b2-eigenlast":["Чому обмеження обладнання є вирішальними під час підйому екскаватором?","На стрілу потрібно підняти важкий вантаж.","В іншому випадку стійкість і допустиме навантаження можуть бути перевищені.","Будь-яка машина може підняти будь-який вантаж, якщо поміщається відро.","Лише довжина мотузки стропа визначає ризик.","Інформація про вантажопідйомність і вантажопідйомність залежить від обладнання та ситуації застосування."],"b2-untergrundhohlraum":["Підлога над старим підвалом може бути порожнистою. що ти робиш","Ви повинні загнати екскаватор в зону.","Перетинайте місце з максимальною інтенсивністю.","Уточніть вантажопідйомність і можливі порожнини перед тим, як рухатися.","Просто помістіть важкий вантаж на поверхню.","Порожнини можуть зруйнуватися під вагою машини та призвести до її збою."],"b2-feuchtigkeit":["Після сильного дощу насип стає м'яким. Що правильно?","Біля краю насипу працює екскаватор.","Перемістіть машину ближче до краю, щоб збільшити охоплення.","Ігнорувати зміни до кінця зміни.","Переоцініть грунт і умови стабільності.","Проникнення вологи може змінити несучу здатність і стійкість насипів."],"b2-bodenprobe":["Чому плани трубопроводу необхідно перевіряти перед розкопками?","Під запланованим котлованом могли пройти кабелі.","Щоб можна було ідентифікувати лінії та спланувати відповідні заходи безпеки.","Щоб розкопки можна було проводити швидше, незалежно від сторонніх систем.","Оскільки машини ніколи не можна використовувати поблизу кабелів.","Підземні підвідні лінії вимагають надійного уточнення розташування перед земляними роботами."],"b2-maschinenzugang":["Що стосується під час посадки та виходу з землерийної машини?","Машина знаходиться на нерівній місцевості.","Посуньте гідравлічну лінію з кабіни.","Використовуйте призначені сходинки та забезпечте надійну опору.","Під час роботи машини стрибайте на поворотний важіль.","Безпечні підйоми та відповідні точки зупинки зменшують ризик падіння та розчавлення."],"b2-kupplung":["Як перевірити новий екскаватор після встановлення?","Ківш підключається через швидкозчіпний пристрій.","Оцінюйте ложку тільки візуально з більшої відстані.","Ступіть прямо під підняту ложку.","Забезпечте правильне замикання та встановлені кроки керування.","Навісне обладнання, яке неправильно заблоковано, може ослабнути та створити небезпеку для людей."],"b2-hydraulikwartung":["Чому не дозволяється відкривати гідролінії під тиском?","Треба замінити шланг.","Витік рідини може спричинити серйозні травми через високий тиск.","Тиск завжди запобігає витіканню масла.","Відкриту лінію можна сміливо перевіряти руками.","Рідина під високим тиском може проникати в тканини і вимагає безпечного скидання тиску."],"b2-fahrweg":["Потрібно проїхати через тимчасовий будівельний міст. Що ти перевіряєш?","Міст розрахований лише на певні навантаження.","Чи відповідає колір моста машині.","Вантажопідйомність і відповідність вазі і розмірам машини.","Тільки чи проїхала вже легка машина по мосту.","Тимчасові споруди можна використовувати лише в межах їх доведеної несучої здатності."],"b2-baggertransport":["Що важливо при транспортуванні екскаватора на низькорамній платформі?","Машину везуть на наступне будівництво.","Нехай робоче обладнання вільно виступає за край.","Тримайте двері кабіни відкритими під час руху.","Закріпіть машину відповідно до специфікацій транспортування та перевірте вантажне обладнання.","Транспортні замки та відповідні засоби для завантаження запобігають ковзанню та падінню."],"b2-schaufelfuellung":["Чому не можна швидко їхати фронтальному навантажувачу з високо піднятим ковшем?","Вантаж важкий, а земля нерівна.","Високий центр ваги може збільшити ризик перекидання та проблеми з видимістю.","Ківш автоматично стабілізується на високих швидкостях.","Висота лопати не має значення для стійкості.","Піднятий центр ваги зазвичай погіршує стійкість під час руху та поворотів."],"b2-fussgaenger":["Як ти поводишся, маневруючи поруч з пішоходами?","Під'їзд до будівельного майданчика також пішохідний.","За допомогою лопати направляйте пішоходів убік.","Виконуйте рух лише тоді, коли територія безпечна та керована.","Просто сигналіть один раз і їдьте повільно без видимості.","Рух транспортних засобів і пасажирів має бути ефективно розділений або безпечно координований."],"b2-ueberlastwarnung":["При підйомі машина повідомляє про перевантаження. що ти робиш","Піднятий вантаж досягає допустимих меж.","Вимкніть попередження та продовжуйте піднімати його без змін.","Під час роботи машини раптово затягніть вантаж.","Зупиніть небезпечні рухи та безпечно виправте ситуацію з вантажем.","Попередження про перевантаження вказують на можливі порушення обмежень і ризики стабільності."],"b2-wasserleitung":["Під час копання виявляють невідому трубу. Що стосується?","На планах будівництва лінія не показана.","Припиніть роботу в зоні ураження та зверніться до фахівця з визначенням лінії.","Спробуйте перемістити лінію лопатою екскаватора.","Продовжуйте копати безпосередньо під лінією без перевірки.","Невідомі лінії можуть спричинити небезпеку електрики, газу або води."],"b2-hangefahrt":["Як вести екскаватор на крутому схилі?","Запланований маршрут проходить по схилу.","Проїжджайте поперек схилу незалежно від обмежень виробника.","Дотримуйтеся допустимого нахилу та встановленого стилю водіння машини.","Відведіть стрілу далеко, щоб збалансувати транспортний засіб.","Допустимий нахил залежить від машини, поверхні та інформації виробника."],"b2-schlechtebeleuchtung":["При роботі в темній ямі видимість недостатня. Що правильно?","Ви майже не бачите людей і перешкод.","Збільште швидкість копання, щоб швидко завершити операцію.","Не використовуйте освітлення, коли двигун працює.","Припиніть роботу, поки небезпечні зони не стануть достатньо видимими.","Для контрольованих рухів машини необхідна безпечна видимість зони руху та роботи."],"b2-kettenverschleiss":["Під час щоденної перевірки помічається пошкоджена гусениця. що ти робиш","Ланцюгове з’єднання демонструє явні пошкодження.","Не продовжуйте використовувати машину безконтрольно та повідомляйте про будь-які пошкодження.","Продовжуйте рух на високій швидкості, щоб ланцюг розпрямився.","Продовжуйте працювати лише на м’якому ґрунті без перевірки.","Пошкодження приводу може погіршити керованість і стабільність."],"b2-ladearbeiten":["Ви завантажуєте вантажівку екскаватором. Що важливо?","Водій вантажівки залишається поряд із зоною завантаження.","Перекинути ківш над незахищеною кабіною водія.","Не допускайте перебування людей у ​​небезпечній зоні та координуйте процеси.","Почніть завантаження без спілкування з водієм.","Під час завантаження існує ризик падіння матеріалу та коливальних рухів."],"b2-arbeitsunterbrechung":["Ви перериваєте земляні роботи заради наради. Що стосується?","Машина повинна стояти кілька хвилин без роботи.","Залиште підняту лопату як маркер.","Залишати машину без нагляду з увімкненим тяговим приводом.","Безпечно встановіть інструмент і захистіть його від ненавмисного використання.","Навіть короткі перерви вимагають безпечного стану машини."],"b2-rollmaterial":["Сипучий матеріал може впасти під час транспортування колісним навантажувачем. Що правильно?","Вантажник їде впритул до співробітників.","Беріть вантаж безпечно та оберіть безпечний стиль водіння з відповідним положенням лопати.","Підніміть лопату якомога вище, щоб було добре видно навколишню територію.","Забирати вантаж без обмеження наповнення ковша.","Сипучі вантажі, високі позиції ковшів і погана видимість можуть загрожувати людям і транспорту."]};
